// Üretilen dosya: tool/ozgun/uret.py. Bilişim ve Algoritmalar · Veritabanı ve SQL sorguları (metinle) (orta).
const ozComputing10Orta = <(String, String, List<String>, String)>[
  ('SELECT fiyat * 1.18 AS kdvli FROM Urun ORDER BY kdvli; sorgusunda ORDER BY içinde takma adın kullanılabilmesinin nedeni nedir?', 'ORDER BY, SELECT listesinden sonra işlendiği için takma adı tanır', ['Takma adlar sorgu boyunca tabloya kalıcı bir sütun olarak eklenir', 'ORDER BY sorgunun ilk işlenen bölümüdür', 'Takma ad yalnız sayısal sütunlarda geçerlidir'], 'Mantıksal işlem sırasında ORDER BY en sonda gelir; SELECT\'te tanımlanan takma adlar o aşamada bilinir.'),
  ('SELECT fiyat * 2 AS cift FROM Urun WHERE cift > 100; sorgusu standart SQL\'de neden hata verir?', 'WHERE, SELECT\'ten önce işlendiği için takma adı henüz tanımaz', ['Takma adlarda rakam kullanılamaz', 'WHERE içinde aritmetik ifade ve karşılaştırma işleci birlikte kullanılamaz', 'AS sözcüğü yalnız tablo adlarına verilebilir'], 'Mantıksal sırada WHERE, SELECT\'ten önce çalışır; bu yüzden koşul WHERE fiyat * 2 > 100 biçiminde yazılmalıdır.'),
  ('PostgreSQL\'de SELECT 7 / 2; sorgusu hangi sonucu döndürür?', '3', ['3.5', '4', '2'], 'İki işlenen de tamsayı olduğunda PostgreSQL tamsayı bölmesi yapar ve kesirli kısmı atar.'),
  ('PostgreSQL\'de iki tamsayı sütunun oranını kesirli olarak elde etmek için en uygun yazım hangisidir?', 'CAST(dogru AS NUMERIC) / toplam', ['dogru / toplam', 'ROUND(dogru / toplam, 2) * 1.0000', 'FLOOR(dogru) / toplam'], 'İşlenenlerden biri NUMERIC\'e çevrilince bölme kesirli yapılır; ROUND ya da FLOOR uygulamak, bölme zaten tamsayıyla yapıldığı için kaybı geri getirmez.'),
  ('30 öğrenciden 12\'sinin başarı yüzdesi PostgreSQL\'de SELECT 12 * 100 / 30; biçiminde, önce çarpılarak hesaplanırsa sonuç ne olur?', '40', ['0', '4', '36'], 'Önce 12 × 100 = 1200 hesaplanır, ardından 1200 / 30 = 40 tamsayı bölmesiyle tam çıkar.'),
  ('SELECT CAST(\'12a\' AS INTEGER); sorgusu PostgreSQL\'de ne olur?', 'Geçersiz tamsayı söz dizimi hatası verir', ['Rakam olmayan kısmı atıp 12 döndürür', '0 döndürür', 'NULL döndürür'], 'PostgreSQL sayıya çevrilemeyen metinde sessizce değer üretmez, hata fırlatır.'),
  ('FLOOR(-2.3) ifadesinin sonucu hangisidir?', '-3', ['-2', '2', '-2.3'], 'FLOOR sayıdan küçük ya da ona eşit en büyük tamsayıyı verir; -2,3\'ten küçük ilk tamsayı -3\'tür.'),
  ('Kargo ücreti her başlamış 5 kg için 20 TL\'dir. 12 kg\'lık bir paket için ücreti hesaplayan ifade hangisidir?', 'CEIL(12 / 5.0) * 20', ['FLOOR(12 / 5.0) * 20', 'ROUND(12 / 5.0) * 20', '(12 % 5) * 20'], '12 / 5 = 2,4; başlamış her dilim sayıldığı için yukarı yuvarlanır: 3 × 20 = 60 TL.'),
  ('Hedef sıcaklık 22 derecedir. Olcum tablosunda hedeften sapması 3 dereceden fazla olan ölçümleri bulan koşul hangisidir?', 'WHERE ABS(sicaklik - 22) > 3', ['WHERE sicaklik - 22 > 3', 'WHERE ABS(sicaklik) - 22 > 3', 'WHERE sicaklik > ABS(22 - 3)'], 'Sapma hem yukarı hem aşağı olabileceği için farkın mutlak değeri alınır.'),
  ('SELECT SIGN(-15), SIGN(0), SIGN(8); sorgusunun sonuçları sırasıyla hangisidir?', '-1, 0, 1', ['15, 0, 8', '1, 0, 1', '-1, 1, 1'], 'SIGN sayının işaretini -1, 0 ya da 1 olarak döndürür.'),
  ('SELECT SUBSTRING(\'Veritabanı\' FROM 5 FOR 5); sorgusunun çıktısı hangisidir?', 'taban', ['itaba', 'abanı', 'Verit'], '5. karakter \'t\' harfidir; buradan başlayarak 5 karakter alınınca \'taban\' elde edilir.'),
  ('SELECT REPLACE(\'kara kutu\', \'u\', \'ü\'); sorgusunun sonucu hangisidir?', 'kara kütü', ['kara kütu', 'kara kutü', 'kere kütü'], 'REPLACE aranan parçanın her geçtiği yeri değiştirir; \'kutu\' içindeki iki \'u\' de \'ü\' olur, \'a\' harflerine dokunulmaz.'),
  ('SELECT POSITION(\'a\' IN \'banana\'); sorgusu hangi sayıyı döndürür?', '2', ['1', '3', '6'], 'POSITION aranan metnin ilk geçtiği konumu verir; \'banana\' içinde ilk \'a\' 2. sıradadır.'),
  ('Sipariş numaraları her zaman 6 haneli gösterilecek ve eksik haneler başa sıfır konarak tamamlanacak. 42 numarası için hangi ifade \'000042\' üretir?', 'LPAD(\'42\', 6, \'0\')', ['RPAD(\'42\', 6, \'0\')', 'LPAD(\'42\', 4, \'0\')', 'REPEAT(\'0\', 6) || \'42\''], 'LPAD metni soldan, istenen uzunluğa ulaşana kadar verilen karakterle doldurur.'),
  ('PostgreSQL\'de bir ad listesini her sözcüğün yalnız ilk harfi büyük olacak biçimde düzenleyen fonksiyon hangisidir?', 'INITCAP', ['UPPER', 'LOWER', 'LPAD'], 'INITCAP her sözcüğün ilk harfini büyük, kalanları küçük yapar; UPPER ve LOWER bütün harfleri aynı biçime çevirir.'),
  ('PostgreSQL\'de SPLIT_PART(\'ali.kaya@okul.edu.tr\', \'.\', 3) ifadesi neyi döndürür?', 'edu', ['kaya@okul', 'tr', 'okul'], 'Metin noktalardan bölününce parçalar ali, kaya@okul, edu ve tr olur; üçüncü parça edu\'dur.'),
  ('Adı LOWER(ad) = \'zeynep\' koşuluyla aramak yerine doğrudan ad = \'zeynep\' ile aramanın kaçırabileceği kayıt hangisidir?', '\'Zeynep\' biçiminde büyük harfle girilmiş kayıt', ['\'zeynep\' biçiminde girilmiş kayıt', 'Adı NULL olan kayıt', 'Adı \'zeynepnur\' olarak bitişik yazılmış kayıt'], 'Çoğu VTYS\'de metin karşılaştırması büyük-küçük harfe duyarlıdır; LOWER iki tarafı aynı biçime getirir.'),
  ('PostgreSQL\'de SELECT \'Ali\' || NULL; ifadesinin sonucu hangisidir?', 'NULL', ['\'Ali\'', '\'AliNULL\'', 'Boş metin'], '|| işlecinde işlenenlerden biri NULL ise sonuç da NULL olur.'),
  ('Metin birleştirme CONCAT(\'Ali\', NULL) fonksiyonuyla yapılırsa PostgreSQL ve MySQL\'de hangi sonuç alınır?', '\'Ali\'', ['NULL', '\'AliNULL\'', 'Hata'], 'CONCAT fonksiyonu NULL argümanları boş metin gibi görür ve yok sayar.'),
  ('CONCAT_WS(\'-\', \'2024\', \'05\', \'17\') ifadesi hangi metni üretir?', '2024-05-17', ['-2024-05-17', '20240517', '2024-05-17-'], 'CONCAT_WS ilk argümanı ayırıcı olarak alır ve onu yalnız değerlerin arasına koyar.'),
  ('Kod sütunundaki tam olarak üç karakterden oluşan değerleri bulan kalıp hangisidir?', 'LIKE \'___\'', ['LIKE \'%%%\'', 'LIKE \'_%_\'', 'LIKE \'3_\''], 'Alt çizgi tam bir karakteri temsil eder; üç alt çizgi üç karakterlik değerlerle eşleşir.'),
  ('ad LIKE \'%a%a%\' koşulu hangi adlarla eşleşir?', 'İçinde en az iki \'a\' harfi bulunan adlarla', ['Yalnız \'a\' harfiyle başlayıp yine \'a\' harfiyle biten adlarla', 'Tam olarak iki harfli adlarla', 'İçinde yan yana iki \'a\' bulunan adlarla'], '% sıfır ya da daha çok karakter yerine geçtiği için iki \'a\' arasında herhangi bir şey olabilir.'),
  ('dosya_adi LIKE \'%.pdf\' koşulu hangi dosya adını seçmez?', 'rapor.pdf.bak', ['ozet.pdf', '2024.pdf', 'a.b.pdf'], 'Kalıp metnin \'.pdf\' ile bitmesini ister; \'rapor.pdf.bak\' \'.bak\' ile bitmektedir.'),
  ('PostgreSQL\'de SELECT DATE \'2024-03-01\' - DATE \'2024-02-01\'; sorgusu hangi değeri döndürür?', '29', ['28', '30', '31'], 'İki DATE değerinin farkı gün sayısıdır; 2024 artık yıl olduğu için şubat 29 gündür.'),
  ('PostgreSQL\'de DATE_TRUNC(\'month\', TIMESTAMP \'2024-05-17 10:30:00\') ifadesi hangi değeri üretir?', '2024-05-01 00:00:00', ['2024-05-17 00:00:00', '2024-06-01 00:00:00', '2024-01-01 00:00:00'], 'DATE_TRUNC verilen birimden küçük alanları sıfırlar; ay düzeyinde kesince ayın ilk gününün gece yarısı kalır.'),
  ('Satislar tablosundaki satış kayıtlarını aylara göre gruplamak isteyen bir analist hangi ifadeyle gruplamalıdır?', 'GROUP BY DATE_TRUNC(\'month\', satis_zamani)', ['GROUP BY EXTRACT(DAY FROM satis_zamani)', 'GROUP BY satis_zamani', 'GROUP BY CURRENT_DATE'], 'DATE_TRUNC her kaydı ait olduğu ayın başlangıcına indirger; aynı aydaki satışlar tek grupta toplanır.'),
  ('Uye tablosunda son 30 gün içinde kaydolan üyeleri PostgreSQL\'de bulan koşul hangisidir?', 'kayit_tarihi >= CURRENT_DATE - 30', ['kayit_tarihi <= CURRENT_DATE - 30', 'kayit_tarihi = CURRENT_DATE - 30', 'kayit_tarihi > CURRENT_DATE + 30'], 'DATE türünden tamsayı çıkarmak o kadar gün geriye gider; bu tarihten sonra kaydolanlar son 30 gündedir.'),
  ('puan 92 olan bir satır için CASE WHEN puan >= 50 THEN \'G\' WHEN puan >= 90 THEN \'O\' ELSE \'K\' END ifadesi ne üretir?', '\'G\'', ['\'O\'', '\'K\'', 'NULL'], 'CASE koşulları yukarıdan aşağı denetler ve ilk doğru olanda durur; 92 ilk koşulu sağladığı için \'O\' dalına hiç bakılmaz.'),
  ('Bir Basvuru tablosunda durum sütunu \'onay\', \'ret\' ya da \'bekliyor\' değerlerini alıyor. Onaylanan başvuru sayısını tek sorguda diğer sayılarla yan yana almak için hangi ifade kullanılır?', 'SUM(CASE WHEN durum = \'onay\' THEN 1 ELSE 0 END)', ['COUNT(durum = \'onay\')', 'MAX(CASE WHEN durum = \'onay\' THEN 1 ELSE NULL END)', 'SUM(durum) WHERE durum = \'onay\''], 'Koşul sağlandığında 1, sağlanmadığında 0 üreten CASE\'in toplamı koşullu sayım verir.'),
  ('Gorev tablosunda oncelik sütunu \'yüksek\', \'orta\', \'düşük\' metinlerini tutuyor. Alfabetik değil de önem sırasına göre sıralamak için ne yapılır?', 'ORDER BY içinde CASE ile her değere bir sıra numarası verilir', ['ORDER BY oncelik DESC yazılır', 'GROUP BY oncelik eklenir ve gruplar sırayla dökülür', 'DISTINCT oncelik kullanılır'], 'Örneğin CASE oncelik WHEN \'yüksek\' THEN 1 WHEN \'orta\' THEN 2 ELSE 3 END ile özel bir sıra tanımlanır.'),
  ('NULLIF(10, 10) ve NULLIF(10, 5) ifadelerinin sonuçları sırasıyla hangisidir?', 'NULL ve 10', ['10 ve NULL', '0 ve 5', 'NULL ve 5'], 'NULLIF iki değer eşitse NULL, değilse ilk değeri döndürür.'),
  ('toplam_tutar / adet bölmesinde adet 0 olan satırların sıfıra bölme hatası vermesini önlemek için yaygın yöntem hangisidir?', 'toplam_tutar / NULLIF(adet, 0)', ['toplam_tutar / COALESCE(adet, 0)', 'toplam_tutar / ABS(adet)', 'toplam_tutar /'], 'adet 0 olduğunda NULLIF NULL döndürür; NULL\'a bölmek hata yerine NULL sonuç verir.'),
  ('Bir fiyatın en az 10 TL olmasını sağlamak için, fiyat 10\'dan küçükse 10\'u, değilse fiyatı veren en kısa ifade hangisidir?', 'GREATEST(fiyat, 10)', ['LEAST(fiyat, 10)', 'MAX(fiyat, 10)', 'COALESCE(fiyat, 10)'], 'GREATEST argümanların en büyüğünü seçer; böylece sonuç hiçbir zaman 10\'un altına inmez.'),
  ('PostgreSQL\'de ORDER BY puan ASC sorgusunda puanı NULL olan satırlar nerede görünür?', 'Sonda', ['Başta', 'Rastgele yerlerde', 'Sonuçtan çıkarılır'], 'PostgreSQL NULL\'u bütün değerlerden büyük sayar; artan sıralamada NULL\'lar sona gelir.'),
  ('PostgreSQL\'de ORDER BY bitis_tarihi DESC kullanılan bir listede bitiş tarihi girilmemiş (NULL) görevlerin en alta inmesi için ne eklenir?', 'NULLS LAST', ['NULLS FIRST', 'IS NOT NULL', 'DESC NULL'], 'Azalan sıralamada PostgreSQL NULL\'ları başa koyar; NULLS LAST bu varsayılanı değiştirir.'),
  ('SELECT ad, maas FROM Calisan ORDER BY 2; sorgusu satırları neye göre sıralar?', 'maas sütununa göre artan', ['ad sütununa göre artan', 'İkinci satırdan başlayarak eklenme sırasına göre', 'Her iki sütuna göre azalan biçimde'], 'ORDER BY\'daki sayı SELECT listesindeki sütunun sırasını gösterir; 2 maas sütunudur ve varsayılan yön artandır.'),
  ('kod sütunu metin türünde ve \'10\', \'9\', \'2\' değerlerini tutuyor. ORDER BY kod ile sıralama sonucu hangisidir?', '\'10\', \'2\', \'9\'', ['\'2\', \'9\', \'10\'', '\'9\', \'2\', \'10\'', '\'10\', \'9\', \'2\''], 'Metinler karakter karakter karşılaştırılır; \'1\' karakteri \'2\' ve \'9\'dan önce geldiği için \'10\' başa çıkar.'),
  ('Sorulardan rastgele 10 tanesini seçmek için PostgreSQL\'de hangi sorgu kullanılır?', 'SELECT * FROM Soru ORDER BY RANDOM() LIMIT 10;', ['SELECT RANDOM(10) FROM Soru;', 'SELECT * FROM Soru LIMIT RANDOM() OFFSET 10 ROWS ONLY;', 'SELECT * FROM Soru WHERE RANDOM() = 10;'], 'Her satıra rastgele bir sayı verilip bu sayıya göre sıralanır; ilk 10 satır rastgele bir örneklem olur.'),
  ('LIMIT 10 OFFSET 25 ifadesi sıralanmış sonucun kaçıncı satırlarını döndürür?', '26 ile 35 arası', ['25 ile 35 arası', '10 ile 25 arası', '26 ile 36 arası'], 'OFFSET 25 ilk 25 satırı atlar; sonraki 10 satır 26. satırdan 35. satıra kadardır.'),
  ('SQL standardında LIMIT yerine ilk 5 satırı almak için tanımlanmış yazım hangisidir?', 'FETCH FIRST 5 ROWS ONLY', ['TAKE FIRST 5 ROWS', 'SELECT FIRST 5 ONLY', 'ROWNUM <= 5 FIRST ROWS ONLY ORDER'], 'SQL:2008 standardı OFFSET ... FETCH FIRST n ROWS ONLY yazımını tanımlar; LIMIT yaygın ama standart dışıdır.'),
  ('Satis tablosunun satırları (Ankara, kitap), (Ankara, defter), (İzmir, kitap), (Ankara, kitap) ise SELECT DISTINCT sehir, urun sorgusu kaç satır döndürür?', '3', ['2', '4', '6'], 'DISTINCT satırın tamamına uygulanır; yalnız (Ankara, kitap) çifti iki kez geçtiği için 4 satırdan 3\'ü kalır.'),
  ('renk sütununun değerleri \'mavi\', NULL, NULL, \'kırmızı\' ise SELECT DISTINCT renk kaç satır verir?', '3', ['2', '4', '1'], 'DISTINCT, NULL değerleri birbirinin tekrarı sayar ve tek satırda toplar: mavi, kırmızı ve NULL.'),
  ('SELECT DISTINCT * FROM Kayit; sorgusu hangi durumda tablonun satır sayısından daha az satır döndürür?', 'Bütün sütunları aynı olan yinelenen satırlar varsa', ['Herhangi bir sütunda en az bir NULL değeri bulunuyorsa', 'Tabloda birincil anahtar tanımlıysa', 'Tablonun satırları sıralı değilse'], 'DISTINCT * yalnız bütün sütunlarıyla birebir aynı olan satırları birleştirir; birincil anahtar varsa böyle satır olamaz.'),
  ('De Morgan kuralına göre WHERE NOT (sehir = \'Rize\' OR yas < 30) koşulunun denk yazımı hangisidir?', 'WHERE sehir <> \'Rize\' AND yas >= 30', ['WHERE sehir <> \'Rize\' OR yas >= 30 OR yas IS NULL', 'WHERE sehir = \'Rize\' AND yas >= 30', 'WHERE sehir <> \'Rize\' AND yas > 30'], 'VEYA\'nın değili, değillerin VE\'sidir; yas < 30\'un değili yas >= 30\'dur.'),
  ('NOT, AND ve OR işleçlerinin SQL\'deki öncelik sırası (yüksekten düşüğe) hangisidir?', 'NOT, AND, OR', ['AND, OR, NOT', 'OR, AND, NOT', 'NOT, OR, AND'], 'NOT en önce, ardından AND, en son OR değerlendirilir; parantez bu sırayı değiştirir.'),
  ('renk sütununda \'yeşil\', \'mavi\' ve NULL değerli üç satır var. WHERE renk <> \'mavi\' koşulu kaç satır döndürür?', '1', ['2', '3', 'Hiç satır döndürmez'], 'NULL <> \'mavi\' karşılaştırması UNKNOWN olur ve satır elenir; yalnız \'yeşil\' kalır.'),
  ('fiyat sütununda NULL yoksa WHERE fiyat < 50 OR fiyat > 100 koşulu hangisine denktir?', 'WHERE fiyat NOT BETWEEN 50 AND 100', ['WHERE fiyat BETWEEN 51 AND 99 OR fiyat IS NULL', 'WHERE fiyat NOT IN', 'WHERE fiyat BETWEEN 100 AND 50'], 'NOT BETWEEN, sınırlar dahil aralığın dışında kalanları seçer: 50\'den küçük ya da 100\'den büyük.'),
  ('NOT IN alt sorgusunun NULL tuzağından kaçınmak için hangi yazım önerilir?', 'NOT EXISTS ile ilişkili alt sorgu', ['IN yerine = ANY yazmak', 'Alt sorguya ORDER BY eklemek', 'NOT IN listesine bir NULL daha eklemek'], 'NOT EXISTS yalnız eşleşen satırın varlığına bakar; NULL değerler sonucu bozmaz.'),
  ('WHERE maas = (SELECT maas FROM Calisan WHERE bolum = \'Satış\') koşulunda alt sorgu üç satır döndürürse ne olur?', 'Sorgu, alt sorgu birden çok satır döndürdü hatası verir', ['Alt sorgunun döndürdüğü ilk satır alınır, diğer iki satır yok sayılır', 'Üç değerin ortalaması kullanılır', 'Koşul kendiliğinden IN gibi çalışır'], '= işleci tek değer bekler; çok satır dönebilecekse IN ya da = ANY kullanılmalıdır.'),
  ('SELECT ad, (SELECT MAX(puan) FROM Sinav WHERE yil = 1990) FROM Ogrenci; sorgusunda 1990 yılına ait hiç sınav yoksa ikinci sütun ne olur?', 'NULL', ['0', 'Sorgu hata verir', 'Ogrenci satırları sonuçtan düşer'], 'Boş kümenin MAX değeri NULL\'dur; skaler alt sorgu bu NULL\'u her satıra koyar.'),
  ('Her ürünün fiyatının genel ortalamadan ne kadar saptığını gösteren sorgu hangisidir?', 'SELECT ad, fiyat - (SELECT AVG(fiyat) FROM Urun) FROM Urun;', ['SELECT ad, fiyat - AVG(fiyat) FROM Urun;', 'SELECT ad, AVG(fiyat) - fiyat FROM Urun GROUP BY ad, fiyat HAVING fiyat > 0;', 'SELECT ad, fiyat FROM Urun WHERE fiyat <> AVG(fiyat);'], 'Kümeleme ile tekil sütun aynı seçimde gruplanmadan karışamaz; ortalama skaler alt sorgudan alınır.'),
  ('Bir öğrenci aynı dersten iki kez kayıtlıysa Ogrenci JOIN Kayit ile yapılan listeleme ve IN alt sorgusuyla yapılan listeleme arasında ne fark görülür?', 'JOIN\'de öğrenci iki kez, IN\'de bir kez görünür', ['IN\'de öğrenci iki kez, JOIN\'de ise yalnız bir kez görünür', 'İkisinde de öğrenci hiç görünmez', 'İkisinde de öğrenci her zaman iki kez görünür'], 'JOIN eşleşen her kayıt için bir satır üretir; IN yalnız varlığı denetlediği için tekrar üretmez.'),
  ('EXISTS (SELECT 1 FROM Siparis WHERE musteri_no = 7) ifadesinde alt sorgudaki \'1\' değerinin önemi nedir?', 'Önemsizdir; EXISTS yalnız satır olup olmadığına bakar', ['Alt sorgunun en çok 1 satır döndürmesini sağlar', 'Müşteri numarası 1 olan satırları arar ve 7 ile karşılaştırır', 'İlk sütunun sayısal olmasını zorunlu kılar'], 'EXISTS döndürülen değerlerle ilgilenmez; tek ölçüt en az bir satırın varlığıdır.'),
  ('Kütüphanede hiç kitap ödünç almamış üyeleri listeleyen koşul hangisidir?', 'WHERE NOT EXISTS (SELECT 1 FROM Odunc o WHERE o.uye_no = u.no)', ['WHERE EXISTS (SELECT 1 FROM Odunc o WHERE o.uye_no <> u.no AND o.iade IS NULL)', 'WHERE NOT EXISTS (SELECT 1 FROM Odunc)', 'WHERE u.no NOT EXISTS Odunc'], 'İlişkili alt sorgu her üye için ödünç kaydı arar; NOT EXISTS hiç kaydı olmayanları seçer.'),
  ('Odunc tablosu tamamen boşken WHERE EXISTS (SELECT 1 FROM Odunc) koşulunu taşıyan bir Uye sorgusu kaç üye döndürür?', 'Hiç üye döndürmez', ['Bütün üyeleri döndürür', 'Yalnız ilk üyeyi döndürür', 'Hata verir ve sorgu durur'], 'İlişkisiz alt sorgu satır üretmediği için EXISTS her satırda FALSE olur.'),
  ('Calisan c tablosunda kendi bölümünün ortalama maaşından fazla kazananları bulan koşul hangisidir?', 'WHERE c.maas > (SELECT AVG(maas) FROM Calisan c2 WHERE c2.bolum = c.bolum)', ['WHERE c.maas > (SELECT AVG(maas) FROM Calisan c2 GROUP BY c2.bolum HAVING COUNT(*) > 1)', 'WHERE c.maas > AVG(c.maas) GROUP BY c.bolum', 'WHERE c.bolum > (SELECT AVG(maas) FROM Calisan c2)'], 'Alt sorgu dış satırın bölümüne bağlıdır; her çalışan kendi bölümünün ortalamasıyla karşılaştırılır.'),
  ('SELECT m.ad, (SELECT COUNT(*) FROM Siparis s WHERE s.mno = m.no) FROM Musteri m; sorgusunda hiç siparişi olmayan bir müşterinin ikinci sütunu ne olur?', '0', ['NULL', 'Müşteri listede yer almaz', 'Hata verir; çünkü alt sorgu boştur'], 'COUNT(*) boş kümede 0 döndürür; müşteri satırı da korunur.'),
  ('Her bölümde en yüksek maaşı alan çalışanları WHERE c.maas = (SELECT MAX(maas) FROM Calisan c2 WHERE c2.bolum = c.bolum) ile bulan sorgu, bir bölümde iki kişi aynı en yüksek maaşı alıyorsa ne yapar?', 'İkisini de listeler', ['Yalnız adı alfabetik önce geleni listeler', 'O bölümden kimseyi listelemez', 'Hata verir'], 'İki çalışanın maaşı da alt sorgudaki en büyük değere eşittir; koşul ikisi için de doğrudur.'),
  ('Bölümlerden ortalama maaşı şirket ortalamasının üzerinde olanları bulmak için alt sorgu nereye yazılır?', 'HAVING AVG(maas) > (SELECT AVG(maas) FROM Calisan)', ['WHERE AVG(maas) > (SELECT AVG(maas) FROM Calisan)', 'ORDER BY (SELECT AVG(maas) FROM Calisan) DESC FETCH FIRST 1 ROW', 'GROUP BY (SELECT AVG(maas) FROM Calisan)'], 'Grup ortalamasıyla yapılan karşılaştırma HAVING\'de yapılır; karşılaştırılacak genel ortalama skaler alt sorgudan gelir.'),
  ('fiyat > ALL (SELECT fiyat FROM Urun WHERE marka = \'X\') koşulu hangisiyle denktir (X ürünü olduğu ve NULL fiyat bulunmadığı varsayılırsa)?', 'X markasının en pahalı ürününden pahalı olmak', ['X markasının en ucuz ürününden pahalı olmak', 'X markasının ortalama fiyatından pahalı olmak', 'X markasının herhangi bir ürünüyle aynı fiyatta olmak'], 'Bütün değerlerden büyük olmak, en büyük değerden büyük olmak demektir.'),
  ('Alt sorgu 15, 25 ve 40 değerlerini döndürüyor. x = 20 için x > ANY (...) ve x > ALL (...) sırasıyla ne verir?', 'TRUE ve FALSE', ['FALSE ve TRUE', 'TRUE ve TRUE', 'FALSE ve FALSE'], '20, 15\'ten büyük olduğu için ANY doğrudur; 25 ve 40\'tan büyük olmadığı için ALL yanlıştır.'),
  ('<> ALL (alt sorgu) karşılaştırması hangi yapının karşılığıdır?', 'NOT IN', ['NOT EXISTS', '<> ANY', 'IS DISTINCT FROM'], 'Listedeki bütün değerlerden farklı olmak, listede bulunmamak demektir; NOT IN ile aynı NULL tuzağını da taşır.'),
  ('SELECT AVG(toplam) FROM (SELECT musteri_no, SUM(tutar) AS toplam FROM Siparis GROUP BY musteri_no) AS t; sorgusu neyi hesaplar?', 'Müşteri başına düşen ortalama sipariş toplamını', ['Bütün siparişlerin tek tek ortalama tutarını', 'En çok sipariş veren müşterinin toplamını', 'Sipariş sayısının müşteri sayısına oranını yüzde olarak'], 'İç sorgu her müşterinin toplamını üretir; dış sorgu bu toplamların ortalamasını alır.'),
  ('FROM içinde kullanılan bir alt sorguya (türetilmiş tabloya) PostgreSQL\'in eski sürümlerinde ve SQL standardında ne verilmesi zorunludur?', 'Bir takma ad', ['Bir birincil anahtar', 'Bir ORDER BY ifadesi', 'Bir indeks'], 'Türetilmiş tablo dış sorguda bir adla anılabilmelidir; FROM (SELECT ...) AS t biçiminde yazılır.'),
  ('Tek bir WITH yan tümcesinde iki CTE tanımlamak için doğru yazım hangisidir?', 'WITH a AS (...), b AS (...) SELECT ...', ['WITH a AS (...) WITH b AS (...) SELECT ...', 'WITH a, b AS (...) (...) SELECT ...', 'WITH a AS (...) AND b AS (...) SELECT ...'], 'CTE\'ler virgülle ayrılır ve WITH sözcüğü yalnız bir kez yazılır; sonraki CTE öncekine başvurabilir.'),
  ('Aynı alt sorgunun bir sorgu içinde üç kez tekrarlandığı durumda CTE kullanmanın başlıca yararı nedir?', 'Sorgunun okunması ve bakımı kolaylaşır', ['Sorgu her zaman üç kat hızlı çalışır', 'Alt sorgunun sonucu diske kalıcı yazılır', 'Sonuçlar kendiliğinden sıralanmış gelir'], 'CTE tekrar eden mantığa bir ad verir; performans etkisi VTYS\'ye ve iyileştiriciye bağlıdır.'),
  ('WITH RECURSIVE s(n) AS (SELECT 1 UNION ALL SELECT n + 1 FROM s WHERE n < 5) SELECT SUM(n) FROM s; sorgusunun sonucu kaçtır?', '15', ['10', '5', 'Sonsuz döngü'], 'Özyineleme 1, 2, 3, 4, 5 değerlerini üretir; n = 5 olunca koşul sağlanmadığı için durur. Toplam 15\'tir.'),
  ('Özyinelemeli bir CTE\'de UNION ALL\'ın üstünde kalan ve özyinelemeye başvurmayan ilk sorguya ne ad verilir?', 'Çapa (anchor) bölümü', ['Özyinelemeli üye', 'Sonlandırma koşulu', 'Türetilmiş görünüm'], 'Çapa başlangıç satırlarını üretir; alttaki özyinelemeli üye her adımda bir önceki adımın satırlarını kullanır.'),
  ('Calisan(id, ad, yonetici_id) tablosunda bir müdürün altındaki bütün kademelerdeki çalışanları bulmak için hangi yapı en uygundur?', 'Özyinelemeli CTE', ['Tek bir INNER JOIN', 'GROUP BY ile HAVING', 'Basit bir IN listesi'], 'Kademe sayısı önceden bilinmediği için ilişki, sonuç boşalana kadar tekrar tekrar izlenmelidir.'),
  ('Özyinelemeli bir CTE\'de WHERE ile bir sonlandırma koşulu yazılmazsa ve veri döngü içeriyorsa ne olur?', 'Sorgu sonsuz döngüye girer ya da sistem sınırında hatayla kesilir', ['Sorgu yalnız çapa satırlarını döndürür', 'VTYS döngüyü her zaman kendiliğinden fark edip tek satır döndürerek durur', 'Sorgu sözdizimi hatasıyla hiç başlamaz'], 'Her adım yeni satır ürettiği sürece özyineleme sürer; sonlandırma koşulu ya da döngü denetimi gerekir.'),
  ('A tablosunun anahtar sütununda 1, 1, 2 değerleri; B tablosunda 1, 1, 1, 3 değerleri var. A INNER JOIN B ON A.anahtar = B.anahtar kaç satır döndürür?', '6', ['2', '3', '12'], 'A\'daki iki 1 değerinin her biri B\'deki üç 1 değeriyle eşleşir: 2 × 3 = 6. 2 ve 3 değerlerinin eşi yoktur.'),
  ('A tablosunun anahtar sütununda 1, 1, 2, B tablosunda 1, 1, 1, 3 değerleri bulunuyor. Anahtar üzerinden A LEFT JOIN B yapılırsa sonuçta kaç satır olur?', '7', ['6', '8', '12'], '6 eşleşen satıra A\'da eşi olmayan 2 değeri için NULL dolgulu bir satır eklenir.'),
  ('Bir INNER JOIN\'de ON A.x = B.x koşulunda iki tarafta da x değeri NULL olan satırlar için ne olur?', 'Eşleşmezler', ['Birbirleriyle eşleşirler', 'Kartezyen çarpım oluşur', 'Sorgu hata verir'], 'NULL = NULL karşılaştırması TRUE olmadığı için bu satırlar birleştirme koşulunu sağlamaz.'),
  ('Calisan tablosunda aynı bölümde çalışan kişi çiftlerini, her çifti bir kez ve kişiyi kendisiyle eşleştirmeden listelemek için hangi koşul kullanılır?', 'a.bolum = b.bolum AND a.id < b.id', ['a.bolum = b.bolum AND a.id <> b.id', 'a.bolum = b.bolum', 'a.bolum <> b.bolum AND a.id = b.id'], '< koşulu hem kişinin kendisiyle eşleşmesini hem de (x, y) ile (y, x) tekrarını önler.'),
  ('Hava(gun, sicaklik) tablosunda sıcaklığın bir önceki güne göre arttığı günleri bulmak için tablo kendisiyle hangi koşulla birleştirilir?', 'bugun.gun = dun.gun + 1 AND bugun.sicaklik > dun.sicaklik', ['bugun.gun = dun.gun AND bugun.sicaklik > dun.sicaklik', 'bugun.gun > dun.gun AND bugun.sicaklik > dun.sicaklik OR dun.gun IS NULL', 'bugun.sicaklik = dun.sicaklik + 1 AND bugun.gun = dun.gun'], 'Tablonun iki kopyası ardışık günler üzerinden eşleştirilir; ardından sıcaklıklar karşılaştırılır.'),
  ('Ogrenci, Kayit ve Ders tablolarını öğrenci adı ile ders adını yan yana göstermek için birleştiren bir sorguda en az kaç birleştirme koşulu gerekir?', '2', ['1', '3', 'Birleştirilen sütun sayısı kadar'], 'n tabloyu kartezyen çarpım oluşturmadan zincirlemek için en az n − 1 birleştirme koşulu gerekir.'),
  ('Siparis JOIN Musteri USING (musteri_no) yazımı neyi ifade eder?', 'İki tablodaki aynı adlı musteri_no sütunu üzerinden eşitlikle birleştirmeyi', ['musteri_no sütununun birleştirmeden sonra sonuç kümesinden tamamen çıkarılmasını', 'Yalnız musteri_no sütununun seçilmesini', 'musteri_no\'ya göre sıralanmış kartezyen çarpımı'], 'USING, aynı adı taşıyan sütun(lar) üzerinden eşitlik birleştirmesinin kısa yazımıdır ve sütunu sonuçta bir kez gösterir.'),
  ('Musteri, Siparis, SiparisKalem ve Urun tablolarından müşteri adı ile aldığı ürün adını getiren bir sorguda birleştirme sırası hangisidir?', 'Musteri – Siparis – SiparisKalem – Urun', ['Musteri – Urun – Siparis – SiparisKalem', 'Urun – Musteri – SiparisKalem – Siparis', 'Siparis – Urun – Musteri – SiparisKalem'], 'Her tablo, yabancı anahtarla bağlı olduğu komşusuna eklenir: müşteri siparişe, sipariş kalemlere, kalem ürüne bağlıdır.'),
  ('Ogrenci(puan) ile HarfNotu(harf, alt, ust) tablolarını her puana doğru harfi verecek biçimde birleştiren koşul hangisidir?', 'ON o.puan BETWEEN h.alt AND h.ust', ['ON o.puan = h.alt', 'ON o.puan = h.harf', 'ON h.alt BETWEEN o.puan AND h.ust + 100'], 'Eşitlik yerine aralık koşuluyla yapılan birleştirme her puanı içine düştüğü aralığın satırıyla eşleştirir.'),
  ('A sorgusu 1, 2, 3, 4 ve B sorgusu 3, 4, 5 değerlerini döndürüyorsa, sıra tersine çevrilerek yazılan B EXCEPT A sonucu hangisidir?', '5', ['1, 2', '3, 4', '1, 2, 5'], 'EXCEPT simetrik değildir; B\'de olup A\'da olmayan tek değer 5\'tir.'),
  ('Oracle veritabanında EXCEPT işleminin karşılığı olan anahtar sözcük hangisidir?', 'MINUS', ['DIFFERENCE', 'SUBTRACT', 'REMOVE'], 'Oracle küme farkı için tarihsel olarak MINUS sözcüğünü kullanır.'),
  ('Kayit tablosunda (sınıf, cinsiyet) çiftleri olarak 9A-K, 9A-E, 9A-K, 9B-K, 9B-K değerleri var. GROUP BY sinif, cinsiyet kaç grup oluşturur?', '3', ['2', '4', '5'], 'Farklı çiftler 9A-K, 9A-E ve 9B-K\'dir; gruplama sütun bileşimine göre yapılır.'),
  ('sehir sütununda \'Van\', NULL, \'Muş\', NULL değerleri bulunan bir tablo için GROUP BY sehir kaç grup üretir?', '3', ['2', '4', 'Gruplama NULL yüzünden hata verir'], 'GROUP BY bütün NULL değerleri tek bir grupta toplar: Van, Muş ve NULL.'),
  ('Bir müşteri tablosunda aynı e-posta adresiyle birden çok kez kaydolmuş adresleri bulmak için hangi sorgu kullanılır?', 'SELECT eposta FROM Musteri GROUP BY eposta HAVING COUNT(*) > 1;', ['SELECT DISTINCT eposta FROM Musteri;', 'SELECT eposta FROM Musteri WHERE COUNT(*) > 1;', 'SELECT eposta, COUNT(*) FROM Musteri ORDER BY COUNT(*) DESC LIMIT 1;'], 'Adresler gruplanır ve birden çok satır içeren gruplar HAVING ile seçilir.'),
  ('Bir anket tablosunda en çok verilen yanıtı (tepe değeri) bulan sorgu hangisidir?', 'SELECT yanit FROM Anket GROUP BY yanit ORDER BY COUNT(*) DESC LIMIT 1;', ['SELECT MAX(yanit) FROM Anket;', 'SELECT yanit FROM Anket ORDER BY yanit DESC LIMIT 1;', 'SELECT yanit, COUNT(DISTINCT yanit) FROM Anket GROUP BY yanit ORDER BY yanit LIMIT 1;'], 'Her yanıtın kaç kez geçtiği sayılıp çoktan aza sıralanır; ilk satır en sık yanıttır.'),
  ('Notlar tablosunda (Ali, 40), (Ali, 80), (Ece, 90), (Ece, 50), (Can, 30) satırları varken SELECT ogrenci FROM Notlar GROUP BY ogrenci HAVING AVG(puan) > 60; hangi öğrencileri döndürür?', 'Yalnız Ece', ['Ali ve Ece', 'Ece ve Can', 'Ali, Ece ve Can'], 'Ortalamalar Ali 60, Ece 70, Can 30\'dur; yalnız Ece 60\'ın üzerindedir.'),
  ('Aylık rapor sorgusunda hiç satış olmayan aylar için toplamın NULL yerine 0 görünmesi için hangi yazım kullanılır?', 'COALESCE(SUM(tutar), 0)', ['SUM(COALESCE(tutar))', 'NULLIF(SUM(tutar), 0)', 'SUM(tutar) IS NULL OR SUM(tutar) = 0'], 'SUM boş kümede NULL döndürür; COALESCE bunu 0 ile değiştirir.'),
  ('PostgreSQL\'de tamsayı türündeki 1 ve 2 değerleri için AVG sonucu nedir?', '1.5', ['1', '2', '1.0000'], 'PostgreSQL tamsayıların ortalamasını NUMERIC türünde verir; kesir atılmaz.'),
  ('PostgreSQL\'de bir bölümdeki çalışan adlarını \'Ali, Banu, Cem\' biçiminde tek metinde birleştiren kümeleme fonksiyonu hangisidir?', 'STRING_AGG(ad, \', \')', ['CONCAT(ad, \', \')', 'GROUP_CONCAT_ALL(ad ORDER BY ad)', 'SUM(ad || \', \')'], 'STRING_AGG grup içindeki değerleri verilen ayırıcıyla birleştirir; MySQL\'deki karşılığı GROUP_CONCAT\'tır.'),
  ('SELECT bolge, SUM(tutar) FROM Satis GROUP BY ROLLUP(bolge); sorgusu 3 bölge için kaç satır döndürür?', '4', ['3', '6', 'Yalnız genel toplam, 1'], 'ROLLUP her bölge için bir satıra ek olarak bütün bölgelerin genel toplamını veren bir satır ekler.'),
  ('Yarışma puanları 100, 90, 90, 80\'dir. RANK() OVER (ORDER BY puan DESC) ifadesi 80 puan için hangi sırayı verir?', '4', ['3', '2', 'Sıra verilmez, NULL'], 'RANK eşit değerlere aynı sırayı verir ve sonra boşluk bırakır: 1, 2, 2, 4.'),
  ('Koşu süreleri 50, 52, 52, 55 saniyedir. DENSE_RANK() OVER (ORDER BY sure) 55 saniye için hangi sırayı üretir?', '3', ['4', '2', '1'], 'DENSE_RANK eşitlikten sonra boşluk bırakmaz: 1, 2, 2, 3.'),
  ('GROUP BY ile pencere fonksiyonu (OVER) arasındaki temel fark nedir?', 'Pencere fonksiyonu satırları tek satıra indirmez', ['Pencere fonksiyonu yalnız sayısal sütunlarla, GROUP BY ise her türle çalışır', 'GROUP BY sonuçları sıralar, pencere fonksiyonu sıralamaz', 'Pencere fonksiyonu WHERE koşulundan önce hesaplanır'], 'OVER ile hesaplanan değer her satırın yanına yazılır; satır sayısı korunur.'),
  ('LAG(satis) OVER (ORDER BY ay) ifadesi ilk ay için hangi değeri döndürür?', 'NULL', ['0', 'İlk ayın kendi satışı', 'Son ayın satışı'], 'İlk satırdan önce satır yoktur; varsayılan değer verilmemişse sonuç NULL olur.'),
  ('İlk satırda NULL yerine 0 görülmesi için LAG fonksiyonu nasıl yazılır?', 'LAG(satis, 1, 0) OVER (ORDER BY ay)', ['LAG(satis, 0) OVER (ORDER BY ay)', 'LAG(0, satis) OVER (ORDER BY ay)', 'LAG(satis) OVER (ORDER BY ay DEFAULT 0)'], 'İkinci argüman kaç satır geriye gidileceğini, üçüncü argüman satır yoksa kullanılacak değeri belirtir.'),
  ('Satışlar sırayla 100, 120, 90 olan üç ay için satis - LAG(satis) OVER (ORDER BY ay) ifadesinin üçüncü aydaki değeri kaçtır?', '-30', ['30', '-10', 'NULL'], 'Üçüncü ayın önceki ayı 120\'dir; 90 − 120 = −30.'),
  ('Bir sınavda her öğrencinin puanını sınıftaki en yüksek puanla karşılaştırmak için, puana göre azalan sıralanmış pencerede hangi fonksiyon işe yarar?', 'FIRST_VALUE(puan)', ['LAST_VALUE(puan)', 'LEAD(puan)', 'NTILE(puan)'], 'Azalan sıralamada pencerenin ilk değeri en yüksek puandır; varsayılan çerçeve her satırda ilk satırı kapsar.'),
  ('Değerler sırayla 3, 6, 9, 12 iken AVG(v) OVER (ORDER BY v ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) dördüncü satırda kaç verir?', '9', ['7.5', '10', '6'], 'Dördüncü satırın çerçevesi kendisi ve önceki iki satırdır: (6 + 9 + 12) / 3 = 9.'),
  ('Her çalışanın maaşının, bütün şirketin maaş toplamı içindeki yüzde payını hesaplayan ifade hangisidir?', 'maas * 100.0 / SUM(maas) OVER ()', ['maas * 100.0 / SUM(maas)', 'maas / COUNT(*) OVER () * 100', 'SUM(maas * 100) OVER (ORDER BY maas)'], 'Boş OVER () bütün sonuç kümesini tek pencere sayar; her satırda genel toplam elde edilir.'),
  ('SUM(tutar) OVER (PARTITION BY musteri ORDER BY tarih) ifadesi ne hesaplar?', 'Her müşteri için tarihe göre biriken toplamı', ['Bütün müşterilerin genel toplamını', 'Her müşterinin yalnız son siparişini', 'Her tarihteki müşteri sayısını'], 'PARTITION BY her müşteri için ayrı pencere açar; ORDER BY toplamı tarih boyunca biriktirir.'),
  ('INSERT INTO Ogrenci VALUES (15, \'Elif\'); komutu, sütun listesi verilmeden yazıldığında hangi koşulu gerektirir?', 'Bütün sütunlara tanım sırasıyla değer verilmesini', ['Tablonun yalnız iki sütunlu olmamasını', 'Değerlerin alfabetik sütun sırasıyla verilmesini', 'Birincil anahtarın en sonda yazılmasını'], 'Sütun listesi yoksa VTYS değerleri tablo tanımındaki sütun sırasına göre yerleştirir; bu yüzden sütun adlarını yazmak daha güvenlidir.'),
  ('2020\'den önceki siparişleri Arsiv tablosuna kopyalamak için hangi komut kullanılır (iki tablonun sütunları aynıdır)?', 'INSERT INTO Arsiv SELECT * FROM Siparis WHERE yil < 2020;', ['INSERT INTO Arsiv VALUES (SELECT * FROM Siparis) WHERE yil < 2020;', 'COPY Siparis TO Arsiv WHERE yil < 2020;', 'UPDATE Arsiv SET * = Siparis.* WHERE yil < 2020;'], 'INSERT ... SELECT yapısı bir sorgunun sonucunu doğrudan başka bir tabloya satır olarak ekler.'),
  ('PostgreSQL\'de yeni eklenen satırın otomatik üretilen numarasını aynı komutla geri almak için INSERT\'ün sonuna ne eklenir?', 'RETURNING id', ['OUTPUT LAST id', 'SELECT LAST_ID', 'GET id AFTER INSERT'], 'RETURNING yan tümcesi eklenen, güncellenen ya da silinen satırların istenen sütunlarını döndürür.'),
  ('Maaşı 5000\'in altındakilere yüzde 10, diğerlerine yüzde 5 zam yapan tek bir UPDATE ifadesi hangisidir?', 'SET maas = maas * CASE WHEN maas < 5000 THEN 1.10 ELSE 1.05 END', ['SET maas = maas * 1.10 WHERE maas < 5000 ELSE 1.05', 'SET maas = CASE maas < 5000 THEN 1.10 ELSE 1.05', 'SET maas = maas * 1.10 WHERE maas < 5000, maas = maas * 1.05 WHERE maas >= 5000'], 'CASE her satır için uygun katsayıyı seçer; tek UPDATE iki farklı zammı birlikte uygular.'),
  ('Urun tablosunda fiyatı NULL olan satırlar varken UPDATE Urun SET fiyat = fiyat + 10; komutundan sonra bu satırların fiyatı ne olur?', 'Yine NULL', ['10', '0', 'Komut hata verir'], 'NULL ile yapılan aritmetik işlemin sonucu NULL\'dur; değer değişmez.'),
  ('Hiç siparişi olmayan müşterileri silen komut hangisidir?', 'DELETE FROM Musteri WHERE no NOT IN (SELECT mno FROM Siparis WHERE mno IS NOT NULL);', ['DELETE FROM Musteri JOIN Siparis WHERE mno IS NULL;', 'DELETE Siparis FROM Musteri WHERE no = mno;', 'DELETE FROM Musteri WHERE EXISTS (SELECT mno FROM Siparis WHERE mno IS NULL OR mno <> 0);'], 'Alt sorgu sipariş veren numaraları listeler; NULL\'ları dışlamak NOT IN tuzağını önler.'),
  ('Bolum tablosundaki bir satır silindiğinde o bölümdeki çalışanların bolum_no alanının boşaltılması, çalışanların ise silinmemesi isteniyor. Yabancı anahtar nasıl tanımlanmalıdır?', 'ON DELETE SET NULL', ['ON DELETE CASCADE', 'ON DELETE RESTRICT', 'ON UPDATE SET DEFAULT ve ON DELETE CASCADE'], 'SET NULL, başvurulan satır silinince başvuran sütunu NULL yapar.'),
  ('Musteri tablosunda bir müşterinin numarası değiştirildiğinde Siparis tablosundaki ilgili numaraların da kendiliğinden güncellenmesi için hangi seçenek kullanılır?', 'ON UPDATE CASCADE', ['ON DELETE CASCADE', 'ON UPDATE SET NULL', 'ON INSERT CASCADE'], 'ON UPDATE CASCADE, birincil anahtar değişikliğini başvuran satırlara yayar.'),
  ('Yabancı anahtarlarda CASCADE tanımlanmamışsa, bir siparişi ve kalemlerini silmek için komutların doğru sırası hangisidir?', 'Önce SiparisKalem satırları, sonra Siparis satırı', ['Önce Siparis satırı, sonra SiparisKalem satırları', 'İkisi aynı anda tek DELETE ile silinmelidir', 'Sıra önemli değildir; VTYS kısıtı komut sonunda denetler'], 'Başvuran (çocuk) satırlar önce silinmezse ana satırın silinmesi yabancı anahtar kısıtına takılır.'),
  ('PostgreSQL\'de INSERT ... ON CONFLICT DO NOTHING ifadesi çakışan bir satır için ne yapar?', 'Satırı eklemeden, hata vermeden geçer', ['Var olan satırı siler ve yenisini ekler', 'Bütün komutu geri alır', 'Çakışan satırı ikinci kez ekler'], 'DO NOTHING, benzersizlik çakışmasında o satırı sessizce atlar.'),
  ('MySQL\'de anahtar çakışması olduğunda eklemeyi güncellemeye çeviren yazım hangisidir?', 'INSERT ... ON DUPLICATE KEY UPDATE ...', ['INSERT ... ON CONFLICT MERGE ...', 'INSERT ... WHEN EXISTS UPDATE ...', 'INSERT ... IF DUPLICATE PRIMARY KEY THEN UPDATE ...'], 'MySQL bu iş için ON DUPLICATE KEY UPDATE yan tümcesini sunar.'),
  ('SQL standardındaki MERGE komutunun tipik kullanımı hangisidir?', 'Kaynaktaki satır hedefte varsa güncellemek, yoksa eklemek', ['İki tabloyu kalıcı olarak tek tabloda birleştirmek', 'İki veritabanını ağ üzerinden birbirine bağlayıp eşzamanlamak', 'Yinelenen satırları tek satırda birleştirip silmek'], 'MERGE ... WHEN MATCHED THEN UPDATE ... WHEN NOT MATCHED THEN INSERT yapısı eşleşmeye göre farklı işlem yapar.'),
  ('Bir Kiralama tablosunda iade tarihinin teslim tarihinden önce olamaması nasıl güvenceye alınır?', 'Tablo düzeyinde CHECK (iade_tarihi >= teslim_tarihi) kısıtıyla', ['iade_tarihi sütununa UNIQUE kısıtı koyarak', 'iade_tarihi sütununa DEFAULT CURRENT_DATE vererek', 'İki tarih sütununu birlikte bileşik birincil anahtar olarak tanımlayarak'], 'Birden çok sütunu karşılaştıran CHECK kısıtları tablo düzeyinde tanımlanabilir.'),
  ('PostgreSQL\'de Ogrenci tablosundaki \'tel\' sütununun adını \'telefon\' yapmak için hangi komut kullanılır?', 'ALTER TABLE Ogrenci RENAME COLUMN tel TO telefon;', ['UPDATE Ogrenci SET tel AS telefon;', 'ALTER COLUMN tel RENAME telefon IN TABLE Ogrenci CASCADE;', 'RENAME Ogrenci.tel TO Ogrenci.telefon;'], 'RENAME COLUMN yalnız sütunun adını değiştirir, içindeki veriye dokunmaz.'),
  ('Kimlik numarası GENERATED ALWAYS AS IDENTITY olan bir tablonun numarası 50 olan en son satırı silinip yeni satır eklenirse yeni satır hangi numarayı alır?', '51', ['50', '1', 'Silinen satırların en küçüğü'], 'Kimlik üreteci yalnız ileri gider; silinen numaralar yeniden kullanılmaz.'),
  ('Bir tablo için (ogrenci_no, ders_kodu) bileşik birincil anahtarı nasıl tanımlanır?', 'PRIMARY KEY (ogrenci_no, ders_kodu)', ['ogrenci_no PRIMARY KEY, ders_kodu PRIMARY KEY', 'PRIMARY KEY ogrenci_no AND ders_kodu', 'UNIQUE KEY (ogrenci_no) + (ders_kodu)'], 'Bileşik anahtar tablo düzeyinde tek PRIMARY KEY yan tümcesinde sütunlar listelenerek tanımlanır; iki ayrı PRIMARY KEY yazılamaz.'),
  ('CREATE TEMPORARY TABLE ile oluşturulan tablo ne zaman ortadan kalkar?', 'Oturum (bağlantı) sona erdiğinde', ['Veritabanı sunucusu kapatılana kadar kalır', 'Bir sonraki SELECT komutundan sonra', 'Hiçbir zaman, elle silinmesi gerekir'], 'Geçici tablolar yalnız onları oluşturan oturuma görünür ve oturumla birlikte silinir.'),
  ('DECIMAL(5,2) türündeki bir sütunun saklayabileceği en büyük değer hangisidir?', '999.99', ['99999.99', '99.999', '5.2'], 'Toplam 5 basamağın 2\'si virgülden sonradır; tam kısma 3 basamak kalır.'),
  ('Para tutarlarını FLOAT yerine DECIMAL türünde saklamanın nedeni nedir?', 'FLOAT ondalık kesirleri tam gösteremez ve yuvarlama hatası birikir', ['DECIMAL her zaman daha az yer kaplar', 'FLOAT türü negatif değer saklayamaz', 'DECIMAL, indekslenebilen ve sıralanabilen tek sayısal veri türüdür'], '0,1 gibi değerler ikilik kayan noktada tam temsil edilemez; DECIMAL ondalık değerleri tam tutar.'),
  ('PostgreSQL\'de CHAR(5) sütununa \'ab\' yazılıp sonra okunduğunda değer nasıl saklanmıştır?', 'Sağdan üç boşlukla 5 karaktere tamamlanmış olarak', ['Soldan üç sıfırla tamamlanmış olarak', 'Yalnız \'ab\' olarak, hiçbir doldurma yapılmadan', 'Hata verilir, çünkü değer tam 5 karakter olmalıdır'], 'CHAR sabit uzunlukludur; kısa değerler boşlukla doldurulur.'),
  ('SMALLINT türündeki bir sütuna 40000 değeri yazılmaya çalışılırsa ne olur?', 'Aralık dışı (taşma) hatası verilir', ['Değer 32767 olarak saklanır', 'Değer otomatik olarak INTEGER\'a dönüştürülür', 'Değer 40000 − 65536 biçiminde eksi sayıya döner'], 'SMALLINT 2 bayttır ve −32768 ile 32767 arasını tutar; PostgreSQL taşmada hata verir.'),
  ('PostgreSQL\'de VARCHAR(10) sütununa 12 karakterlik bir metin eklenirse ne olur?', '\'Değer bu tür için çok uzun\' hatası verilir', ['İlk 10 karakter saklanır, kalan sessizce atılır', 'Sütunun boyu otomatik olarak 12\'ye çıkar', 'Metin iki satıra bölünerek saklanır'], 'PostgreSQL fazladan boşluk dışındaki karakterleri kesmeden hata verir; bazı başka VTYS\'ler ayara göre keser.'),
  ('PostgreSQL\'de iki TIMESTAMP değerinin farkı hangi türde bir sonuç verir?', 'INTERVAL', ['INTEGER', 'DATE', 'NUMERIC'], 'Zaman damgalarının farkı \'3 days 04:00:00\' gibi bir süre (INTERVAL) değeridir.'),
  ('π_ad(σ_yas>20(Ogrenci)) ilişkisel cebir ifadesinin SQL karşılığı hangisidir?', 'SELECT DISTINCT ad FROM Ogrenci WHERE yas > 20;', ['SELECT yas FROM Ogrenci WHERE ad > 20;', 'SELECT * FROM Ogrenci WHERE ad = 20 GROUP BY yas;', 'SELECT ad, yas FROM Ogrenci ORDER BY yas > 20;'], 'σ satırları süzer (WHERE), π sütun seçer (SELECT); kuramsal cebir küme kullandığı için DISTINCT eklenir.'),
  ('R(A, B, C) ve S(C, D) ilişkilerinin doğal birleşiminin (R ⋈ S) derecesi kaçtır?', '4', ['5', '3', 'Satır sayısına bağlı'], 'Ortak sütun C sonuçta bir kez yer alır: A, B, C ve D.'),
  ('İki ilişkiye birleşim (∪) ya da fark (−) uygulanabilmesi için hangi koşul gerekir?', 'Birleşim uyumlu olmaları: aynı sayıda ve uyumlu alanlı sütunlar', ['Aynı sayıda satır içermeleri', 'Ortak bir birincil anahtarı paylaşmaları', 'Aralarında tanımlı bir yabancı anahtar ilişkisi ve ortak birincil anahtar bulunması'], 'Küme işlemleri demetleri karşılaştırdığı için iki tarafın sütun yapısı eşleşmelidir.'),
  ('İlişkisel cebirdeki ρ (ro) işleminin görevi nedir?', 'İlişkiyi ya da sütunlarını yeniden adlandırmak', ['Satırları belirli bir koşula göre süzmek', 'İki ilişkinin kartezyen çarpımını almak', 'Yinelenen demetleri belirli bir sütuna göre sıralayıp silmek'], 'Yeniden adlandırma, özellikle bir ilişki kendisiyle birleştirilirken iki kopyayı ayırt etmek için gerekir.'),
  ('Koşulu A.fiyat > B.fiyat olan bir birleştirme ilişkisel cebirde nasıl adlandırılır?', 'Teta birleştirme (θ-join)', ['Doğal birleştirme', 'Eş birleştirme (equi-join)', 'Bölme işlemi'], 'Eşitlik dışındaki karşılaştırma işleçleriyle tanımlanan birleştirmeye teta birleştirme denir; eş birleştirme onun yalnız = kullanan özel durumudur.'),
  ('R(A, B, C, D) ilişkisinde F = {A → B, B → C, C → D} bağımlılıkları geçerlidir. A\'nın kapanışı (A⁺) hangisidir?', '{A, B, C, D}', ['{A, B}', '{A, B, C}', '{B, C, D}, A kendisi hariç'], 'A → B\'den B, B → C\'den C, C → D\'den D eklenir; A bütün nitelikleri belirler.'),
  ('AB → A biçimindeki bir işlevsel bağımlılık neden \'önemsiz\' (trivial) sayılır?', 'Sağ taraf sol tarafın alt kümesidir', ['Sol taraf tek bir nitelikten oluşur', 'Bağımlılık hiçbir tabloda sağlanmaz, çünkü çelişkilidir', 'Sağ tarafta birincil anahtar vardır'], 'Sağ tarafı sol tarafın içinde kalan bağımlılık her ilişkide kendiliğinden doğrudur.'),
  ('A → BC bağımlılığından A → B çıkarılabilir mi?', 'Evet, ayrıştırma kuralıyla', ['Hayır, yalnız A → BC geçerlidir', 'Yalnız B birincil anahtarsa', 'Evet, ama yalnız A → C ile birlikte yazılırsa'], 'Bir nitelik kümesini belirleyen X, o kümenin her alt kümesini de belirler.'),
  ('SELECT DISTINCT sehir FROM Musteri; sorgusu hangisiyle aynı satırları döndürür?', 'SELECT sehir FROM Musteri GROUP BY sehir;', ['SELECT sehir FROM Musteri ORDER BY sehir;', 'SELECT COUNT(sehir) FROM Musteri;', 'SELECT sehir FROM Musteri HAVING COUNT(*) = 1;'], 'Kümeleme fonksiyonu olmadan GROUP BY her farklı değer için bir satır üretir; DISTINCT ile aynı işi görür.'),
  ('A LEFT JOIN B ON A.id = B.aid WHERE B.aid IS NOT NULL sorgusu hangisine denktir?', 'A INNER JOIN B ON A.id = B.aid', ['A RIGHT JOIN B ON A.id = B.aid WHERE A.id IS NULL', 'A FULL JOIN B ON A.id = B.aid', 'A CROSS JOIN B'], 'Eşi olmayan A satırları B sütunlarında NULL taşır; IS NOT NULL bu satırları atınca yalnız eşleşmeler kalır.'),
  ('SELECT ad FROM Personel WHERE maas > 5000 ORDER BY maas GROUP BY bolum; sorgusundaki yapısal hata hangisidir?', 'GROUP BY, ORDER BY\'dan önce yazılmalıdır', ['WHERE, FROM\'dan önce gelmelidir', 'ORDER BY sütunu SELECT listesinde bulunmalıdır', 'GROUP BY yalnız sayısal sütunlarla kullanılabilir'], 'Yan tümcelerin yazım sırası SELECT, FROM, WHERE, GROUP BY, HAVING, ORDER BY biçimindedir.'),
  ('SELECT * FROM Musteri WHERE sehir = "Bursa"; sorgusu PostgreSQL\'de neden hata verir?', 'Çift tırnak bir tanımlayıcıyı (sütun adını) gösterir, metni değil', ['Şehir adları büyük harfle başlayamaz', 'WHERE içinde = işleci metin türündeki değerlerle hiçbir zaman kullanılamaz', 'Noktalı virgül sorgunun sonuna yazılamaz'], 'Standart SQL\'de çift tırnak sütun ya da tablo adı içindir; PostgreSQL \'Bursa\' adında bir sütun arar.'),
  ('Bir geliştirici \'hiç kayıt yapılmamış dersleri\' bulmak için Ders d JOIN Kayit k ON d.kod = k.kod WHERE k.kod IS NULL yazıyor. Sorgu neden her zaman boş döner?', 'INNER JOIN eşi olmayan dersleri zaten dışarıda bıraktığı için', ['IS NULL yerine = NULL yazılması gerektiği için, aksi hâlde koşul hep yanlıştır', 'Ders tablosunda kod sütunu bulunmadığı için', 'JOIN yalnız iki sütunla yapılabildiği için'], 'Eşi olmayan satırları görmek için LEFT JOIN gerekir; INNER JOIN sonrasında k.kod hiç NULL olmaz.'),
  ('WHERE YEAR(kayit_tarihi) = 2023 koşulu, kayit_tarihi sütununda indeks varken neden verimsizdir?', 'Sütun fonksiyona sarıldığı için indeks doğrudan kullanılamaz', ['YEAR fonksiyonu artık yıllarda şubat ayı için yanlış yıl değeri üretir', 'Tarih sütunlarında indeks oluşturulamaz', 'Koşul her zaman tam iki satır döndürür'], 'İndeks sütunun kendi değerlerine göre sıralıdır; fonksiyon sonucu üzerinden aranırken her satırın hesaplanması gerekir.'),
  ('kayit_tarihi sütununda indeks varken 2023 yılı kayıtlarını indeksi kullanabilecek (sargable) biçimde süzen koşul hangisidir?', 'WHERE kayit_tarihi >= \'2023-01-01\' AND kayit_tarihi < \'2024-01-01\'', ['WHERE EXTRACT(YEAR FROM kayit_tarihi) = 2023', 'WHERE CAST(kayit_tarihi AS TEXT) LIKE \'2023-%\' AND kayit_tarihi IS NOT NULL', 'WHERE kayit_tarihi + 0 = 2023'], 'Sütun yalın bırakılıp sabit bir aralıkla karşılaştırılınca indeks üzerinde aralık taraması yapılabilir.'),
  ('fiyat sütununda indeks varken WHERE fiyat * 1.2 > 600 koşulunun indeks dostu yazımı hangisidir?', 'WHERE fiyat > 500', ['WHERE fiyat * 1.2 > 600.0', 'WHERE ROUND(fiyat * 1.2) > 600', 'WHERE fiyat > 600 * 1.2'], 'Hesap sabit tarafa taşınır: 600 / 1,2 = 500. Böylece sütun yalın kalır.'),
  ('WHERE ad LIKE \'Mer%\' ile WHERE ad LIKE \'%met\' koşullarından hangisi ad üzerindeki B-ağacı indeksinden yararlanabilir?', 'Yalnız \'Mer%\' kalıbı', ['Yalnız \'%met\' kalıbı', 'İki kalıp da eşit ölçüde', 'İki kalıp da indeksten yararlanamaz'], 'Sabit önekli kalıp indeks sırasında bir başlangıç noktası verir; % ile başlayan kalıp vermez.'),
  ('CREATE VIEW Ucuz AS SELECT * FROM Urun WHERE fiyat < 100 WITH CHECK OPTION; görünümü üzerinden fiyatı 250 olan bir ürün eklenmeye çalışılırsa ne olur?', 'Ekleme, görünüm koşulunu sağlamadığı için reddedilir', ['Ürün eklenir ama görünümde görünmez', 'Ürünün fiyatı otomatik olarak 99 yapılır', 'Ürün yalnız görünüme eklenir, temel tabloya ise hiçbir zaman yazılmaz'], 'WITH CHECK OPTION, görünüm üzerinden yapılan eklemelerin ve güncellemelerin görünümün WHERE koşulunu sağlamasını zorunlu kılar.'),
  ('Var olan bir görünümün tanımını, onu silmeden yeni bir sorguyla değiştirmek için hangi yazım kullanılır?', 'CREATE OR REPLACE VIEW', ['ALTER VIEW ... SET QUERY', 'UPDATE VIEW ... AS', 'MODIFY VIEW ... TO'], 'CREATE OR REPLACE VIEW görünüm varsa tanımını yeniler, yoksa oluşturur.'),
  ('Tek bir tabloyu temel alan, kümeleme ve DISTINCT içermeden yalnız bazı sütunları seçen bir görünüm üzerinden UPDATE yapılması için çoğu VTYS\'de hangisi doğrudur?', 'Güncelleme doğrudan temel tabloya yansıtılarak yapılabilir', ['Görünümler hiçbir koşulda güncellenemez', 'Güncelleme yalnız görünümde saklanır', 'Önce görünümün somutlaştırılması ve ardından yenilenmesi gerekir'], 'Basit görünümlerde her görünüm satırı tek bir tablo satırına karşılık geldiği için VTYS değişikliği temel tabloya aktarabilir.'),
  ('PostgreSQL\'de somutlaştırılmış bir görünümün (materialized view) içeriğini temel tablolardaki son verilerle güncellemek için hangi komut kullanılır?', 'REFRESH MATERIALIZED VIEW', ['UPDATE MATERIALIZED VIEW', 'RELOAD VIEW', 'COMMIT MATERIALIZED VIEW WITH DATA'], 'Somutlaştırılmış görünüm sonucu diskte tutar; güncel olması için REFRESH ile yeniden hesaplanmalıdır.'),
  ('GRANT SELECT ON Rapor TO mert WITH GRANT OPTION; komutundaki WITH GRANT OPTION ne sağlar?', 'mert\'in bu okuma yetkisini başka kullanıcılara da verebilmesini', ['mert\'in tabloyu silebilmesini', 'Yetkinin süresiz değil, yalnız o anki oturum boyunca geçerli olmasını', 'mert\'in tablo yapısını değiştirebilmesini'], 'WITH GRANT OPTION, alıcının aldığı yetkiyi başkalarına devretme hakkıdır.'),
  ('Elli muhasebe çalışanına aynı yetkileri tek tek vermek yerine en düzenli yöntem hangisidir?', 'Bir rol oluşturup yetkileri role vermek ve çalışanları role eklemek', ['Bütün çalışanlara aynı kullanıcı adını vermek', 'Yetkileri PUBLIC\'e vermek', 'Her çalışan için tablonun ayrı bir kopyasını oluşturup yetkileri kopyalara tek tek vermek'], 'Rol tabanlı yetkilendirmede yetkiler bir kez role tanımlanır; çalışan eklendiğinde ya da ayrıldığında yalnız rol üyeliği değişir.'),
  ('Bir kullanıcıya maaş sütununu içermeyen bir görünüm üzerinde SELECT yetkisi verilip temel tablo üzerinde hiçbir yetki verilmezse ne olur?', 'Kullanıcı görünümü okuyabilir ama maaşları göremez', ['Kullanıcı görünümü de okuyamaz', 'Kullanıcı temel tablonun bütün sütunlarını görebilir', 'Görünüm üzerinden maaş sütunu da otomatik eklenir'], 'Görünüm yetkisi, temel tabloya doğrudan erişim vermeden verinin sınırlı bir kesitini paylaşmayı sağlar.'),
  ('Bakiyesi 1000 olan bir hesapta sırasıyla BEGIN; bakiye + 100; SAVEPOINT s1; bakiye + 50; ROLLBACK TO s1; COMMIT; işletiliyor. Son bakiye kaçtır?', '1100', ['1150', '1000', '1050'], 'ROLLBACK TO s1 yalnız kayıt noktasından sonraki +50\'yi geri alır; +100 COMMIT ile kalıcı olur.'),
  ('Bir işlem SELECT ... FROM Koltuk WHERE no = 12 FOR UPDATE; çalıştırdığında ne olur?', 'Okunan satır, işlem bitene kadar başka işlemlerin güncellemesine karşı kilitlenir', ['Satır silinir ve yeniden eklenir', 'Satır yalnız okunur, hiçbir kilit alınmaz', 'Bütün tablo salt okunur yapılır, diğer oturumların okumaları da işlem bitene kadar bekletilir'], 'FOR UPDATE satır düzeyinde yazma kilidi alır; aynı koltuğun iki kez satılmasını önlemek için kullanılır.'),
  ('Bir işlemin izolasyon seviyesini SERIALIZABLE yapmak için işlemin başında hangi komut kullanılır?', 'SET TRANSACTION ISOLATION LEVEL SERIALIZABLE;', ['ALTER TRANSACTION SERIALIZABLE;', 'BEGIN TRANSACTION WITH SERIALIZABLE LOCK ON ALL TABLES;', 'SET ISOLATION = MAX;'], 'İzolasyon seviyesi SET TRANSACTION ISOLATION LEVEL ile işlem bazında belirlenir.'),
  ('Bir sonuç sütununa içinde boşluk bulunan \'Toplam Tutar\' takma adını vermek için standart SQL\'de nasıl yazılır?', 'AS "Toplam Tutar"', ['AS \'Toplam Tutar\' ve tek tırnak zorunlu', 'AS Toplam Tutar', 'AS [Toplam_Tutar] köşeli ayraçla zorunlu'], 'Boşluk içeren tanımlayıcılar standart SQL\'de çift tırnak içinde yazılır.'),
  ('Ad sütununda O\'Brien soyadını aramak için metin sabiti nasıl yazılır?', '\'O\'\'Brien\'', ['\'O\'Brien\'', '"O\'Brien"', '\'O\\\\Brien\' ters bölüyle'], 'Standart SQL\'de tek tırnak içindeki bir tek tırnak, iki kez yazılarak gösterilir.'),
  ('\'user\' ya da \'order\' gibi ayrılmış sözcükleri sütun adı olarak kullanmak zorunda kalan bir geliştirici ne yapmalıdır?', 'Adı çift tırnak içinde yazmalıdır', ['Adı tek tırnak içinde yazmalıdır', 'Adın başına # işareti koymalıdır', 'Bu sözcükler hiçbir biçimde ad olamaz, kalıcı hata verir'], 'Tırnaklı tanımlayıcı ayrılmış sözcüğü sıradan bir ad olarak kullanmayı sağlar; yine de bu tür adlardan kaçınmak önerilir.'),
  ('CREATE TABLE Bos AS SELECT * FROM Musteri WHERE 1 = 0; komutu ne üretir?', 'Musteri\'yle aynı sütunlara sahip ama hiç satırı olmayan bir tablo', ['Musteri\'nin bütün satırlarının bir kopyası', 'Yalnız ilk satırı içeren bir tablo', 'Sütunsuz, boş bir tablo ve koşulun her zaman yanlış olduğunu bildiren uyarı mesajı'], '1 = 0 hiçbir satır için doğru olmadığı için yalnız sütun yapısı kopyalanır.'),
  ('SELECT COUNT(1) FROM Siparis; sorgusu COUNT(*) ile karşılaştırıldığında ne verir?', 'Aynı sonucu, yani satır sayısını', ['Yalnız ilk sütunu NULL olmayan satırları', 'Her zaman 1', 'Birinci sütundaki farklı değerlerin sayısını'], '1 sabiti hiçbir satırda NULL olmadığı için her satır sayılır.'),
  ('Bir uygulama, kullanıcının seçtiği süzgeçlere göre koşulları ekleyerek SQL oluşturuyor ve sorguyu WHERE 1 = 1 ile başlatıyor. Bunun amacı nedir?', 'Her yeni koşulun başına AND koyarak kolayca eklenebilmesi', ['Sorgunun daha hızlı çalışması', 'Bütün satırların her zaman döndürülmesinin zorunlu kılınması', 'SQL enjeksiyonunun tamamen engellenmesi'], '1 = 1 her zaman doğrudur ve sonucu değiştirmez; ardından gelen her koşul \'AND ...\' biçiminde eklenebilir.'),
  ('Bir PostgreSQL veritabanındaki bütün tabloların adlarını standart SQL ile listelemek için hangi kaynak sorgulanır?', 'information_schema.tables', ['pg_all_rows', 'SYSTEM.TABLES_LIST', 'Veritabanındaki her tablonun ilk satırı tek tek'], 'information_schema, veritabanı nesnelerini tanımlayan standart görünümleri içerir.'),
  ('Bir tablonun sütun adlarını ve veri türlerini sorguyla öğrenmek için information_schema içindeki hangi görünüm kullanılır?', 'columns', ['tables', 'views', 'routines'], 'information_schema.columns her sütunun tablo adını, sütun adını, veri türünü ve NULL olup olamayacağını gösterir.'),
  ('Bir veritabanının tablolar, sütunlar, kısıtlar ve kullanıcılar hakkındaki bilgileri tuttuğu iç yapıya genel olarak ne ad verilir?', 'Sistem kataloğu', ['İşlem günlüğü', 'Arabellek havuzu', 'Sorgu önbelleği ve yürütme planı'], 'Katalog, veritabanının kendisini tanımlayan üst veriyi (metadata) tutar.'),
  ('Urun tablosunda fiyatlar 10 (X), 20 (Y) ve 30 (X) olarak kayıtlı. UPDATE Urun SET fiyat = fiyat * 2 WHERE kategori = \'X\'; komutundan sonra SUM(fiyat) kaçtır?', '100', ['120', '80', '60'], 'X kategorisindeki 10 ve 30, 20 ve 60 olur; Y\'deki 20 değişmez. Toplam 20 + 20 + 60 = 100.'),
  ('Bagis tablosunda (İzmir, 100), (İzmir, 250), (Van, 300), (Muş, 50), (Muş, 80) satırları var. GROUP BY sehir HAVING SUM(miktar) > 200 kaç şehir döndürür?', '2 (İzmir ve Van)', ['3 (bütün şehirler)', '1 (yalnız Van)', '5 (her satır ayrı)'], 'Toplamlar İzmir 350, Van 300, Muş 130\'dur; 200\'ü aşan İzmir ve Van\'dır.'),
  ('Puanlar 70, 85, 40 ve 95\'tir. SELECT ROUND(AVG(puan), 0) FROM Sinav WHERE puan >= 50; sonucu kaçtır?', '83', ['73', '72', 'Hesaplanamaz, NULL'], 'WHERE 40\'ı atar; (70 + 85 + 95) / 3 = 83,33 olur ve en yakın tamsayıya yuvarlanır.'),
  ('Sınıf A\'da Ali 80 ve Ece 90, sınıf B\'de Can 70 puan almıştır. ROW_NUMBER() OVER (PARTITION BY sinif ORDER BY puan DESC) Ali için kaç verir?', '2', ['1', '3', 'NULL'], 'A sınıfı penceresinde Ece 90 ile 1., Ali 80 ile 2. olur; B sınıfı ayrı numaralanır.'),
  ('indirim sütunu 5, NULL ve 10 değerlerini tutuyorsa SUM(indirim) ve SUM(COALESCE(indirim, 0)) sırasıyla kaçtır?', '15 ve 15', ['NULL ve 15', '15 ve NULL', '5 ve 15'], 'SUM zaten NULL\'ları atlar; NULL\'u 0 yapmak toplamı değiştirmez.'),
  ('Rehberdeki numaralar \'0532 123 45 67\' biçiminde boşluklu girilmiş. SELECT LENGTH(REPLACE(\'0532 123 45 67\', \' \', \'\')); sorgusu kaç döndürür?', '11', ['14', '10', '3'], 'REPLACE bütün boşlukları boş metinle değiştirir; geriye 05321234567 kalır ve bu 11 karakterdir.'),
  ('Urun tablosunda kodlar \'A-10\', \'B-7\', \'A-3\' ve \'A-25\' olarak kayıtlı. SELECT COUNT(*) FROM Urun WHERE kod LIKE \'A-_\'; sorgusu kaç döndürür?', '1', ['3', '2', '4'], 'Alt çizgi tam bir karakter yerine geçer; \'A-\' sonrasında tek karakter bulunan yalnız \'A-3\' kalıba uyar.'),
  ('Karma (hash) indeks hangi tür sorguda işe yarar, hangisinde yaramaz?', 'Eşitlik aramasında yarar, aralık aramasında yaramaz', ['Aralık aramasında yarar, eşitlik aramasında yaramaz', 'LIKE \'%x\' aramasında yarar, eşitlikte yaramaz', 'Her türlü sorguda, aralık ve sıralama dahil, B-ağacından daha iyi sonuç verir'], 'Karma değerler sıralı değildir; yalnız = karşılaştırması için doğrudan konum verir.'),
  ('Siparis.musteri_no yabancı anahtar sütununa indeks eklemek genellikle neden önerilir?', 'Birleştirmeler ve silme sırasındaki denetimler hızlanır', ['Yabancı anahtar indeks olmadan tanımlanamaz', 'Sipariş eklemeleri her zaman hızlanır, çünkü indeks yazma işini azaltır', 'Müşteri numaraları otomatik olarak sıralanır'], 'Birleştirmeler ve başvurulan satır silinirken yapılan bağımlı kayıt aramaları bu sütun üzerinden yürür.'),
  ('EXPLAIN çıktısında \'Seq Scan on Urun\' satırı ne anlatır?', 'Tablonun baştan sona tarandığını', ['Urun tablosunda bir indeksin kullanıldığını', 'Sorgunun hata verdiğini', 'Urun tablosunun sıralanarak diske yeniden yazıldığını'], 'Seq Scan tam tablo taramasıdır; indeksli erişim \'Index Scan\' olarak görünür.'),
  ('PostgreSQL\'de güncellenen ve silinen satırlardan kalan ölü kayıtların yerini geri kazanan bakım komutu hangisidir?', 'VACUUM', ['REINDEX', 'CLUSTER ALL', 'TRUNCATE'], 'MVCC yüzünden eski satır sürümleri hemen silinmez; VACUUM bu alanı yeniden kullanılabilir yapar.'),
  ('Bir tabloya milyonlarca satır yüklendikten sonra PostgreSQL\'de ANALYZE çalıştırmanın amacı nedir?', 'Sorgu iyileştiricinin kullandığı istatistikleri güncellemek', ['Tablodaki hatalı satırları bulup silmek', 'Bütün sorguları önceden çalıştırıp sonuçlarını kalıcı önbelleğe almak', 'Tabloyu sıkıştırıp diskteki boyutunu yarıya indirmek'], 'İyileştirici plan seçerken satır sayısı ve değer dağılımı istatistiklerine dayanır; bunlar eskirse kötü plan seçilebilir.'),
  ('PostgreSQL\'de WHERE kod ~ \'^[A-Z]{2}[0-9]{3}\$\' koşulu ne yapar?', 'İki büyük harf ve üç rakamdan oluşan kodları seçer', ['Kodu yaklaşık (bulanık) olarak karşılaştırır', 'Kodu sayıya çevirip 2 ile 3 arasındakileri seçer', 'Kodları alfabetik olarak tersten sıralar'], '~ işleci PostgreSQL\'de büyük-küçük harfe duyarlı düzenli ifade eşleştirmesidir.'),
  ('Bir web sayfası önce 50 yazarı tek sorguyla getiriyor, sonra her yazarın kitapları için ayrı ayrı 50 sorgu daha çalıştırıyor. Bu kalıba ne ad verilir?', 'N+1 sorgu sorunu', ['Kartezyen patlama', 'Kirli okuma sorunu', 'Kilitlenme (deadlock) zinciri'], 'Bir ana sorgu ve her satır için bir ek sorgu ağ gidiş-gelişlerini çoğaltır; JOIN ya da IN ile tek sorguda çözülebilir.'),
  ('10.000 satırı eklerken her satır için ayrı INSERT göndermek yerine çok satırlı INSERT ya da toplu yükleme kullanmak neden daha hızlıdır?', 'Ağ gidiş-gelişleri ve işlem başına ek yük azalır', ['Satırlar diske sıkıştırılmadan yazılır', 'Kısıtlar hiç denetlenmez', 'İndeksler eklemeden sonra kendiliğinden silinir ve yeniden kurulmaz'], 'Her ayrı komut kendi iletişim, ayrıştırma ve çoğu zaman onay maliyetini taşır; toplu işlem bunu paylaştırır.'),
  ('Uygulama kodunda SELECT * yerine gereken sütunları açıkça yazmanın yararı hangisidir?', 'Gereksiz veri taşınmaz ve tabloya sütun eklenince kod bozulmaz', ['Sorgu her zaman indeks kullanır', 'NULL değerler sonuçtan kendiliğinden çıkar', 'Sorgu, parametre kullanılmasa bile SQL enjeksiyonuna karşı tamamen korunmuş olur'], 'Açık sütun listesi ağ trafiğini azaltır, kapsayan indeks kullanımına olanak verir ve şema değişikliklerine karşı dayanıklıdır.'),
  ('SELECT ders, AVG(puan) FROM Notlar GROUP BY ders HAVING MIN(puan) >= 50; sorgusu hangi derslerin ortalamasını getirir?', 'Hiçbir öğrencinin 50\'nin altında kalmadığı derslerin', ['Ortalaması 50 ve üzeri olan derslerin', 'En az 50 öğrencisi olan derslerin', '50\'nin altındaki notlar atıldıktan sonra bütün derslerin'], 'Grubun en düşük notu 50 veya üzerindeyse o dersteki bütün notlar 50 veya üzerindedir.'),
  ('SELECT a.ad, b.ad FROM Takim a CROSS JOIN Takim b WHERE a.id <> b.id; sorgusu 4 takım için kaç satır üretir?', '12', ['16', '6', '8'], 'Her takım kendisi dışındaki 3 takımla eşleşir; iç saha ve dış saha ayrı sayıldığı için 4 × 3 = 12 maç çıkar.'),
  ('SELECT MAX(maas) FROM Calisan WHERE maas < (SELECT MAX(maas) FROM Calisan); sorgusu maaşlar 9000, 9000, 7000 ve 5000 iken ne döndürür?', '7000', ['9000', '5000', 'NULL'], 'İç sorgu 9000\'i bulur; 9000\'den küçüklerin en büyüğü 7000\'dir. Bu yazım ikinci en yüksek farklı değeri verir.'),
  ('FROM Ogrenci o, Sinif s WHERE o.sinif_id = s.id biçimindeki eski yazım hangi birleştirmeyle aynı sonucu verir?', 'Ogrenci INNER JOIN Sinif ON o.sinif_id = s.id', ['Ogrenci LEFT JOIN Sinif ON o.sinif_id = s.id', 'Ogrenci CROSS JOIN Sinif', 'Ogrenci FULL JOIN Sinif ON o.sinif_id = s.id WHERE s.id IS NULL'], 'Virgülle kartezyen çarpım alınıp WHERE ile eşitlik konunca iç birleştirme elde edilir.'),
  ('Calisan tablosunda (1, Ayla, yönetici yok), (2, Burak, 1), (3, Cem, 1), (4, Dila, 2) satırları var. Tablo c.yonetici_id = y.id koşuluyla kendisiyle INNER JOIN yapılırsa kaç satır çıkar?', '3', ['4', '2', '16'], 'Yöneticisi olan Burak, Cem ve Dila eşleşir; yönetici alanı NULL olan Ayla iç birleştirmede düşer.'),
  ('Özyinelemeli bir sorgu Ayla\'yı (en üst yönetici) 1. düzey kabul ederek kademeleri sayıyor. Burak\'ın ekibindeki Dila hangi düzeydedir?', '3', ['2', '4', '1'], 'Ayla 1, ona bağlı Burak 2, Burak\'a bağlı Dila 3. düzeydir.'),
  ('SELECT urun, SUM(CASE WHEN yil = 2022 THEN tutar END) AS y2022, SUM(CASE WHEN yil = 2023 THEN tutar END) AS y2023 FROM Satis GROUP BY urun; sorgusu ne üretir?', 'Her ürün için yılların ayrı sütunlarda yer aldığı bir özet', ['Her yıl için ürünlerin ayrı satırlarda yer aldığı ham liste', 'Yalnız iki yılda da satışı olan ürünleri', 'Ürünlerin iki yıl arasındaki farkını tek sütunda gösteren ve azalan sıralanmış liste'], 'Koşullu toplama satır değerlerini (yıl) sütunlara dağıtır; buna pivot (döndürme) denir.'),
  ('Pivot sorgusunda 2022\'de satışı olmayan bir ürün için y2022 sütununda ne görünür?', 'NULL', ['0', 'Ürün listelenmez', 'Hata verir; CASE\'de ELSE zorunludur'], 'CASE\'in ELSE dalı yoksa eşleşmeyen satırlar NULL üretir; bütün değerleri NULL olan bir SUM da NULL olur.'),
  ('Musteri (1, 2, 3) ve Siparis müşteri numaraları (1, 1, 3) iken SELECT COUNT(*) FROM Musteri m WHERE EXISTS (SELECT 1 FROM Siparis s WHERE s.mno = m.no); kaç döndürür?', '2', ['3', '1', '4'], 'EXISTS her müşteriyi bir kez değerlendirir; siparişi olan 1 ve 3 numaralı müşteriler sayılır.'),
  ('Sinif tablosunda (A, 20 öğrenci), (B, 25 öğrenci), (C, 15 öğrenci) satırları var. SELECT sinif FROM Sinif WHERE ogr_sayisi > (SELECT AVG(ogr_sayisi) FROM Sinif); hangi sınıfı döndürür?', 'B', ['A', 'C', 'A ve B'], 'Ortalama (20 + 25 + 15) / 3 = 20\'dir; 20\'den büyük olan yalnız B\'dir, A eşit olduğu için seçilmez.'),
  ('\'15/08/2023\' biçimindeki bir metni PostgreSQL\'de DATE türüne çeviren ifade hangisidir?', 'TO_DATE(\'15/08/2023\', \'DD/MM/YYYY\')', ['TO_CHAR(\'15/08/2023\', \'DD/MM/YYYY\')', 'CAST(\'15/08/2023\' AS DATE FORMAT \'MM/DD\')', 'DATE_TRUNC(\'day\', \'15/08/2023\' AS TEXT)'], 'TO_DATE metni verilen kalıba göre çözümleyip tarihe çevirir; TO_CHAR ise ters yönde çalışır.'),
  ('PostgreSQL\'de TRIM(LEADING \'0\' FROM \'00420\') ifadesinin sonucu hangisidir?', '\'420\'', ['\'42\'', '\'00420\'', '\'4200\''], 'LEADING yalnız baştaki sıfırları kaldırır; sondaki 0 olduğu gibi kalır.'),
  ('Bir sütunun değerleri 5, 5 ve 10 ise SUM(DISTINCT x) ve SUM(x) sırasıyla kaçtır?', '15 ve 20', ['20 ve 15', '10 ve 20', '15 ve 15'], 'DISTINCT önce yinelenen 5\'i atar: 5 + 10 = 15; DISTINCT olmadan 5 + 5 + 10 = 20.'),
  ('Telefon sütununun bütün değerleri NULL olan bir rehber tablosu için COUNT(telefon) ne döndürür?', '0', ['NULL', 'Satır sayısı', 'Hata verir'], 'COUNT(sütun) NULL olmayan değerleri sayar; hiç yoksa sonuç 0\'dır. SUM ise aynı durumda NULL döndürür.'),
  ('PostgreSQL\'de ARRAY_AGG(etiket) kümeleme fonksiyonu bir grup için ne üretir?', 'Gruptaki değerlerden oluşan bir dizi', ['Değerlerin toplamını', 'Farklı değerlerin sayısını', 'Değerleri virgülle birleştiren bir metin ve sayısı'], 'ARRAY_AGG değerleri {a,b,c} biçiminde bir dizi değerine toplar; UNNEST bunun tersini yapar.'),
  ('PostgreSQL\'de SELECT UNNEST(ARRAY[3, 6, 9]); sorgusu kaç satır döndürür?', '3', ['1', '9', '18'], 'UNNEST diziyi açar ve her öğeyi ayrı bir satıra koyar.'),
  ('PostgreSQL\'de WHERE id = ANY(ARRAY[4, 8, 15]) koşulu hangisine denktir?', 'WHERE id IN (4, 8, 15)', ['WHERE id = 4 AND id = 8 AND id = 15', 'WHERE id BETWEEN 4 AND 15', 'WHERE id > ALL (4, 8, 15)'], '= ANY bir dizinin herhangi bir öğesine eşitliği sınar; uygulamadan dizi parametresi göndermek için kullanışlıdır.'),
  ('PostgreSQL\'de Kayit tablosunun bütün satırlarını silip kimlik numaralarını da 1\'den yeniden başlatmak için hangi komut kullanılır?', 'TRUNCATE Kayit RESTART IDENTITY;', ['DELETE FROM Kayit RESET;', 'TRUNCATE Kayit KEEP IDENTITY;', 'DROP TABLE Kayit; ve ardından numaralar elle 1 yapılır'], 'RESTART IDENTITY, tabloya bağlı dizileri de sıfırlar; varsayılan CONTINUE IDENTITY sayacı korur.'),
  ('PostgreSQL\'de fatura_no adlı diziden (sequence) sıradaki numarayı almak için hangi fonksiyon çağrılır?', 'nextval(\'fatura_no\')', ['currval(\'fatura_no\') + 1', 'setval(\'fatura_no\')', 'lastval() ile dizinin adı birlikte'], 'nextval diziyi ilerletip yeni değeri döndürür; currval aynı oturumda son alınan değeri gösterir.'),
  ('Bir formda e-posta alanını hiç doldurmayan (NULL) ya da boş bırakıp gönderen (\'\') üyeleri PostgreSQL\'de birlikte bulan koşul hangisidir?', 'WHERE eposta IS NULL OR eposta = \'\'', ['WHERE eposta = NULL OR eposta = \'\'', 'WHERE eposta = \'\'', 'WHERE LENGTH(eposta) = 0 AND eposta IS NOT NULL OR eposta LIKE \'%\''], 'PostgreSQL\'de boş metin NULL değildir; iki durum ayrı ayrı denetlenip VEYA ile birleştirilmelidir.'),
  ('SQL dilinin resmî standardını hangi kuruluşlar yayımlar?', 'ANSI ve ISO', ['IEEE ve W3C', 'IETF ve ICANN', 'Oracle ve IBM ortaklığıyla kurulan SQL Vakfı'], 'SQL ilk kez 1986\'da ANSI, 1987\'de ISO standardı olmuştur; sonraki sürümler ISO/IEC 9075 adıyla yayımlanır.'),
  ('PostgreSQL\'in komut satırı istemcisi psql\'de veritabanındaki tabloları listeleyen kısa komut hangisidir?', '\\dt', ['\\q', '\\help tables', 'SHOW ALL TABLES;'], 'psql\'de ters bölüyle başlayan meta komutlar vardır: \\dt tabloları listeler, \\q çıkış yapar.'),
  ('Bir ankette yalnız bir kez verilmiş yanıtları listeleyen sorgu hangisidir?', 'SELECT yanit FROM Anket GROUP BY yanit HAVING COUNT(*) = 1;', ['SELECT DISTINCT yanit FROM Anket;', 'SELECT yanit FROM Anket WHERE COUNT(*) = 1;', 'SELECT yanit FROM Anket GROUP BY yanit HAVING COUNT(DISTINCT yanit) = 1 ORDER BY yanit;'], 'DISTINCT tekrar edenleri de birer kez gösterir; yalnız bir kez geçenler için grup sayısı 1 olmalıdır.'),
  ('Market ürünlerinin fiyatları 12, 7, 30 ve 7 TL\'dir. SELECT MIN(fiyat), COUNT(DISTINCT fiyat) FROM Urun; sonucu nedir?', '7 ve 3', ['7 ve 4', '12 ve 3', '7 ve 2'], 'En küçük fiyat 7\'dir; farklı fiyatlar 7, 12 ve 30 olmak üzere üç tanedir.'),
  ('Bir Satis tablosundan yalnız içinde bulunulan yılın kayıtlarını getiren PostgreSQL koşulu hangisidir?', 'EXTRACT(YEAR FROM tarih) = EXTRACT(YEAR FROM CURRENT_DATE)', ['tarih = CURRENT_DATE', 'EXTRACT(YEAR FROM tarih) = CURRENT_DATE', 'tarih > CURRENT_DATE - 1 AND tarih <= CURRENT_DATE + 365 AND tarih IS NOT NULL'], 'İki tarafın yıl alanı karşılaştırılır; CURRENT_DATE\'in kendisi bir tarihtir, yıl değildir.'),
  ('Log tablosunun bütün sütunları varsayılan değer taşıyorsa, değer vermeden tek satır ekleyen standart yazım hangisidir?', 'INSERT INTO Log DEFAULT VALUES;', ['INSERT INTO Log VALUES ();', 'INSERT INTO Log NULL;', 'INSERT DEFAULT ROW INTO Log WITH ALL COLUMNS;'], 'DEFAULT VALUES, her sütun için tanımlı varsayılan değeri (yoksa NULL) kullanarak bir satır ekler.'),
  ('BOOLEAN türündeki aktif sütununun değerini her satırda tersine çeviren (TRUE ise FALSE, FALSE ise TRUE yapan) komut hangisidir?', 'UPDATE Uye SET aktif = NOT aktif;', ['UPDATE Uye SET aktif = -aktif;', 'UPDATE Uye SET aktif = TRUE OR FALSE;', 'UPDATE Uye SET NOT aktif = aktif WHERE aktif IS TRUE OR aktif IS FALSE;'], 'NOT mantıksal değeri tersine çevirir; NULL değerler NOT ile yine NULL kalır.'),
  ('Çoğu ilişkisel VTYS\'de bir sütuna PRIMARY KEY kısıtı tanımlanınca kendiliğinden ne oluşturulur?', 'O sütun üzerinde benzersiz bir indeks', ['Sütunun bir yedek kopyası', 'Bir tetikleyici ve bir saklı yordam', 'Sütuna bağlı bir görünüm ve somutlaştırılmış kopyası'], 'Benzersizliği hızlı denetleyebilmek için VTYS birincil anahtar için otomatik bir benzersiz indeks kurar.'),
  ('Siparis tablosunda tutarlar 250, 400, 150 ve 400\'dür. SELECT tutar FROM Siparis ORDER BY tutar DESC LIMIT 2; hangi değerleri döndürür?', '400 ve 400', ['400 ve 250', '250 ve 150', '400'], 'Azalan sırada ilk iki satır iki ayrı 400 değeridir; LIMIT yinelenenleri ayıklamaz.'),
  ('Bir tablonun satırlarını, başka bir tablonun içinde eşi bulunup bulunmadığına göre (eşi çoğaltmadan) seçen EXISTS tabanlı işleme veritabanı kuramında ne ad verilir?', 'Yarı birleştirme', ['Dış birleştirme', 'Kartezyen birleştirme', 'Doğal birleştirme ve ardından izdüşüm'], 'Yarı birleştirme yalnız soldaki satırları, eşleşme varsa bir kez döndürür; sağ tablonun sütunları sonuca gelmez.'),
  ('Her siparişi, o müşterinin ortalama sipariş tutarıyla karşılaştırmak için Siparis tablosu hangi yapıyla birleştirilebilir?', 'Müşteri başına ortalamayı veren türetilmiş tabloyla', ['Musteri tablosunun kendisiyle CROSS JOIN ile', 'Siparis tablosunun DISTINCT kopyasıyla', 'GROUP BY tutar ile gruplanmış ve ORDER BY ile sıralanmış hâliyle'], 'Türetilmiş tablo müşteri başına bir ortalama satırı üretir; mno üzerinden birleştirilince her siparişin yanına gelir.'),
  ('Müşteri başına sipariş sayısını hesaplayan bir sorguda GROUP BY m.ad yerine GROUP BY m.no kullanılması neden daha doğrudur?', 'Aynı adı taşıyan farklı müşteriler tek grupta birleşmez', ['Sayısal sütunlarda gruplama her zaman daha hızlıdır ve sonuç değişmez', 'Ad sütunu GROUP BY ile hiç kullanılamaz', 'no sütunu NULL olabileceği için ayrı bir grup açar'], 'Ad benzersiz değildir; iki \'Ali Yılmaz\' tek satırda toplanıp sayıları karışır. Benzersiz anahtar her müşteriyi ayırır.'),
  ('Her müşterinin son sipariş tarihini müşteri listesinin yanında göstermek için SELECT içinde hangi alt sorgu kullanılabilir?', '(SELECT MAX(s.tarih) FROM Siparis s WHERE s.mno = m.no)', ['(SELECT MAX(tarih) FROM Siparis)', '(SELECT tarih FROM Siparis WHERE mno = no ORDER BY tarih)', '(SELECT LAST(tarih) FROM Siparis GROUP BY mno HAVING mno = m.no AND tarih IS NOT NULL)'], 'İlişkili skaler alt sorgu her müşteri için yalnız onun siparişlerinin en büyük tarihini döndürür.'),
  ('Her öğrencinin puanının kendi sınıfındaki en yüksek puandan ne kadar geride olduğunu gösteren ifade hangisidir?', 'MAX(puan) OVER (PARTITION BY sinif) - puan', ['MAX(puan) - puan GROUP BY sinif', 'puan - LAG(puan) OVER', 'RANK() OVER (PARTITION BY sinif ORDER BY puan DESC) - puan'], 'Pencere fonksiyonu her satıra sınıfın en yüksek puanını getirir; fark her öğrencinin açığını verir.'),
  ('Bir randevu listesinde her randevunun yanına aynı hastanın bir sonraki randevu tarihini getiren ifade hangisidir?', 'LEAD(tarih) OVER (PARTITION BY hasta_no ORDER BY tarih)', ['LAG(tarih) OVER (PARTITION BY hasta_no ORDER BY tarih)', 'MAX(tarih) OVER (PARTITION BY hasta_no)', 'LEAD(tarih) OVER (ORDER BY hasta_no, tarih ROWS UNBOUNDED PRECEDING)'], 'LEAD sonraki satırı getirir; PARTITION BY hasta_no başka hastaların randevularına geçilmesini önler.'),
  ('Fatura numaraları ardışık olmalıdır. Atlanan numaraları bulmak için her satırda no + 1 değeri hangi ifadeyle karşılaştırılabilir?', 'LEAD(no) OVER (ORDER BY no)', ['LAG(no) OVER (ORDER BY no)', 'COUNT(*) OVER ()', 'ROW_NUMBER() OVER (ORDER BY no DESC)'], 'Bir sonraki numara no + 1\'e eşit değilse arada atlanmış numara vardır.'),
  ('Günlük satış kayıtlarında her gün için son 7 günün (o gün dahil) toplamını veren çerçeve tanımı hangisidir? (Her gün bir satır vardır.)', 'ROWS BETWEEN 6 PRECEDING AND CURRENT ROW', ['ROWS BETWEEN 7 PRECEDING AND CURRENT ROW', 'ROWS BETWEEN CURRENT ROW AND 6 FOLLOWING', 'ROWS BETWEEN UNBOUNDED PRECEDING AND 7 FOLLOWING'], 'Geçerli satır ile önceki 6 satır toplam 7 günü kapsar; 7 PRECEDING sekiz gün eder.'),
  ('Her satırın yanına sorgu sonucundaki toplam satır sayısını yazmak için hangi ifade kullanılır?', 'COUNT(*) OVER ()', ['COUNT(*) GROUP BY ()', 'ROW_NUMBER() OVER ()', 'SUM(1) OVER (ORDER BY id ROWS BETWEEN CURRENT ROW AND CURRENT ROW)'], 'Boş pencere bütün sonucu kapsar; her satırda aynı toplam sayı görünür.'),
  ('Her müşterinin ilk sipariş tarihini sipariş satırlarının yanına yazan FIRST_VALUE(tarih) OVER (PARTITION BY mno ORDER BY tarih) ifadesiyle aynı sonucu veren daha basit ifade hangisidir?', 'MIN(tarih) OVER (PARTITION BY mno)', ['MAX(tarih) OVER (PARTITION BY mno)', 'MIN(tarih) OVER ()', 'LAG(tarih) OVER (PARTITION BY mno ORDER BY tarih)'], 'Tarihe göre artan sıralamada ilk değer, bölümdeki en küçük tarihtir.'),
  ('Bütün dersleri alan öğrencileri GROUP BY ile bulmak için Alir(ogr, ders) tablosunda hangi HAVING koşulu yazılır?', 'HAVING COUNT(DISTINCT ders) = (SELECT COUNT(*) FROM Ders)', ['HAVING COUNT(*) > 1', 'HAVING MAX(ders) = (SELECT MAX(ders) FROM Ders)', 'HAVING COUNT(ders) >= 1 AND ders IN'], 'Öğrencinin aldığı farklı ders sayısı toplam ders sayısına eşitse bütün dersleri almıştır.'),
  ('A sorgusu 7, 7, 8 ve B sorgusu 7, 7, 7 değerlerini döndürüyor. A INTERSECT ALL B kaç satır verir?', '2', ['1', '3', '5'], 'INTERSECT ALL her değeri iki taraftaki en küçük tekrar sayısı kadar tutar: 7 değeri A\'da 2, B\'de 3 kez olduğu için 2 kez kalır; 8 B\'de yoktur.'),
  ('SELECT ad FROM A UNION SELECT ad FROM B ORDER BY ad; sorgusundaki ORDER BY neye uygulanır?', 'Birleşimin tamamına', ['Yalnız ikinci sorguya', 'Yalnız birinci sorguya', 'Her iki sorguya ayrı ayrı uygulanıp sonuçlar art arda yazılır'], 'Küme işleminden sonra gelen ORDER BY bütün sonucu sıralar; ara sorgulara ayrı sıralama yazılamaz.'),
  ('SELECT ad AS isim FROM Ogretmen UNION SELECT ogrenci_adi FROM Ogrenci; sonucundaki sütunun adı ne olur?', 'isim', ['ogrenci_adi', 'ad', 'Ad verilmez; sütun numarayla anılır'], 'Küme işlemlerinde sonuç sütunlarının adları ilk sorgudan alınır.'),
  ('Bir okul öğrenci ve öğretmenlerin adlarını tek listede, kimin hangi gruptan geldiğini belirterek göstermek istiyor. Hangi yazım uygundur?', 'SELECT ad, \'öğrenci\' FROM Ogrenci UNION ALL SELECT ad, \'öğretmen\' FROM Ogretmen;', ['SELECT ad FROM Ogrenci JOIN Ogretmen USING (ad);', 'SELECT ad FROM Ogrenci INTERSECT SELECT ad FROM Ogretmen;', 'SELECT Ogrenci.ad, Ogretmen.ad, \'öğrenci\', \'öğretmen\' FROM Ogrenci, Ogretmen ORDER BY 1;'], 'Her sorguya sabit bir etiket sütunu eklenir; UNION ALL iki listeyi kayıpsız alt alta koyar.'),
  ('SELECT k.ad, u.ad FROM Kitap k LEFT JOIN Odunc o ON o.kitap_no = k.no LEFT JOIN Uye u ON u.no = o.uye_no; sorgusu ne listeler?', 'Bütün kitapları, ödünç alınmışsa alan üyeyle birlikte', ['Yalnız ödünç alınmış kitapları', 'Yalnız hiç ödünç alınmamış kitapları', 'Bütün üyeleri, hiç kitap almamış olsalar bile, aldıkları kitaplarla'], 'Sol tablo Kitap olduğu için hiçbir kitap düşmez; eşi olmayan kitapta üye adı NULL görünür.'),
  ('DATE türündeki tarih sütununda WHERE tarih BETWEEN \'2023-01-01\' AND \'2023-01-31\' koşulu hangi kayıtları seçer?', 'Ocak 2023\'teki bütün günlerin kayıtlarını', ['31 Ocak hariç Ocak kayıtlarını', 'Yalnız 1 ve 31 Ocak kayıtlarını', 'Ocak ve Şubat 2023 kayıtlarını, sınır günleri dahil'], 'DATE türünde saat bilgisi yoktur; BETWEEN iki sınırı da kapsadığı için ayın 31 gününün hepsi seçilir.'),
  ('ALTER TABLE Urun ADD CONSTRAINT fiyat_pozitif CHECK (fiyat > 0); komutu ne yapar?', 'Fiyatın sıfırdan büyük olmasını şart koşan adlandırılmış bir kısıt ekler', ['Negatif fiyatları sıfıra çevirir', 'Fiyat sütununu siler ve yeniden oluşturur', 'Fiyatı sıfır ya da negatif olan var olan satırları kendiliğinden tablodan siler'], 'Kısıt eklenirken var olan satırlar da denetlenir; uymayan satır varsa komut başarısız olur.'),
  ('SELECT bolum, MAX(maas) FROM Calisan GROUP BY bolum; sorgusu bir bölümde aynı en yüksek maaşı alan iki kişi varsa kaç satır döndürür (o bölüm için)?', '1', ['2', '0', 'Bölümdeki çalışan sayısı kadar'], 'Gruplamada her bölüm tek satıra iner; MAX yalnız değeri verir, kaç kişinin aldığını göstermez.'),
  ('SQL standardındaki izolasyon seviyelerinden hangisi tekrarlanamayan okumayı önler ama standarda göre hayalet okumaya izin verebilir?', 'REPEATABLE READ', ['READ COMMITTED', 'READ UNCOMMITTED', 'SERIALIZABLE ya da READ COMMITTED'], 'REPEATABLE READ okunan satırların değişmemesini güvenceye alır; yeni eklenen satırlara karşı tam koruma SERIALIZABLE\'dadır.'),
  ('PostgreSQL\'de bir işlem için izolasyon seviyesi belirtilmezse varsayılan seviye hangisidir?', 'READ COMMITTED', ['SERIALIZABLE', 'REPEATABLE READ', 'READ UNCOMMITTED'], 'PostgreSQL\'de her komut, o komut başladığı ana kadar onaylanmış verileri görür.'),
  ('Stok düşürme işini SELECT stok ... ile okuyup uygulamada hesaplayarak ayrı bir UPDATE ile yazmak yerine UPDATE Urun SET stok = stok - 1 WHERE id = 5 AND stok > 0; yazmak neden daha güvenlidir?', 'Okuma ve yazma tek atomik komutta yapıldığı için kayıp güncelleme oluşmaz', ['Komut indeks kullanmadığı için daha hızlıdır', 'Stok sütunu otomatik olarak kilitlenmez', 'Komut işlem (transaction) dışında çalıştığı için geri alınamaz ve kalıcıdır'], 'Araya başka işlemin yazısı giremez; stok > 0 koşulu da eksiye düşmeyi engeller.'),
  ('İyimser kilitlemede UPDATE Belge SET icerik = ..., surum = surum + 1 WHERE id = 9 AND surum = 4; komutu 0 satır etkilediyse bu ne anlama gelir?', 'Kayıt bu arada başka biri tarafından değiştirilmiştir', ['Komut başarılı olmuş, değişiklik kaydedilmiştir', 'id = 9 olan kayıt hiçbir zaman var olmamıştır', 'Veritabanı salt okunur kipe geçmiş ve bütün yazma komutları reddediliyordur'], 'Sürüm numarası okunduğu andakinden farklıysa koşul tutmaz; uygulama çakışmayı kullanıcıya bildirip veriyi yeniden okumalıdır.'),
  ('Bir tablonun içinde koşula uyan satır olup olmadığını öğrenmek için IF (SELECT COUNT(*) ...) > 0 yerine EXISTS kullanmak neden genellikle daha verimlidir?', 'EXISTS ilk eşleşen satırı bulunca durur, COUNT bütün eşleşmeleri sayar', ['COUNT(*) NULL satırları da saydığı için yanlış sonuç verir', 'EXISTS sonucu önbelleğe yazar ve bir daha hesaplamaz', 'COUNT(*) yalnız indeksli sütunlarda çalışır, EXISTS her sütunda çalışır'], 'Varlık sorusu için bütün satırları saymak gereksizdir; EXISTS kısa devre yapar.'),
  ('Birleştirilecek iki listenin ortak satırı olmadığı biliniyorsa UNION yerine UNION ALL kullanmak neden tercih edilir?', 'Yinelenenleri ayıklamak için gereken sıralama ya da karma işi yapılmaz', ['UNION ALL sonuçları alfabetik olarak sıralar', 'UNION, ortak satır yoksa hata verir', 'UNION ALL sütun türlerini denetlemez, böylece her türlü sütunu birleştirir'], 'UNION her satırı diğerleriyle karşılaştırmak zorundadır; gereksizse bu maliyetten kaçınılır.'),
  ('Bir birleştirme sorgusu beklenen 500 yerine 250.000 satır döndürüyor. En olası neden hangisidir?', 'Birleştirme koşulu eksik ya da yanlış sütun üzerinden yazılmıştır', ['Tabloda indeks yoktur', 'Sorguda ORDER BY kullanılmıştır', 'Sütun takma adları çok uzun seçilmiştir ve ayrıştırıcı bunları satır olarak yorumlamıştır'], 'Satır sayısının çarpım düzeyinde artması, kartezyen çarpıma yakın bir eşleşme olduğunu gösterir.'),
  ('Tek satırlık bir Ayar(kdv_orani) tablosundaki oranı bütün ürün satırlarına eklemek için hangi birleştirme uygundur?', 'Urun CROSS JOIN Ayar', ['Urun INNER JOIN Ayar ON Urun.id = Ayar.kdv_orani', 'Urun FULL JOIN Ayar', 'Urun NATURAL JOIN Ayar'], 'Tek satırla çapraz birleştirme her ürüne aynı ayar değerini ekler; satır sayısı değişmez.'),
  ('Raporlarda boş günleri de göstermek için her günün bir satır olduğu yardımcı tabloya genellikle ne ad verilir?', 'Takvim tablosu', ['Olgu tablosu', 'Geçici günlük tablo', 'İşlem günlüğü'], 'Takvim tablosu tarih, ay, haftanın günü gibi bilgileri önceden tutar; dış birleştirmeyle eksik günleri tamamlar.'),
  ('PostgreSQL\'de CREATE TYPE ruh_hali AS ENUM (\'mutlu\', \'üzgün\', \'kızgın\'); ile tanımlanan bir sütunun özelliği nedir?', 'Yalnız listedeki değerleri alır ve bu sırayla sıralanır', ['Her türlü metni kabul eder', 'Değerleri alfabetik sıraya göre sıralar', 'Her değeri otomatik olarak bir sayıya çevirip saklar ve sayı olarak gösterir'], 'ENUM türü sabit değer kümesi tanımlar; sıralama tanımdaki sıraya göre yapılır.'),
  ('Birincil anahtar olarak artan tamsayı yerine UUID kullanmanın başlıca yararı hangisidir?', 'Merkezî sayaç olmadan çakışmasız kimlik üretilebilir', ['Daha az yer kaplar ve indeksi her zaman daha hızlıdır', 'Kayıtların eklenme sırasını kesin olarak gösterir', 'İnsanların ezberlemesi ve telefonda söylemesi kolaydır'], 'UUID\'ler 128 bittir ve bağımsız üretilse de çakışma olasılığı yok denecek kadar azdır; bedeli daha büyük indekslerdir.'),
  ('MySQL\'in InnoDB depolama motorunda varsayılan izolasyon seviyesi hangisidir?', 'REPEATABLE READ', ['READ COMMITTED', 'SERIALIZABLE', 'READ UNCOMMITTED'], 'InnoDB varsayılan olarak REPEATABLE READ kullanır; PostgreSQL ve SQL Server\'da ise varsayılan READ COMMITTED\'dır.'),
  ('PostgreSQL\'de Urun tablosundaki fiyat sütununun türünü NUMERIC(10,2) yapmak için hangi komut kullanılır?', 'ALTER TABLE Urun ALTER COLUMN fiyat TYPE NUMERIC(10,2);', ['UPDATE Urun SET fiyat = NUMERIC(10,2);', 'ALTER TABLE Urun CHANGE fiyat TO NUMERIC;', 'CAST TABLE Urun COLUMN fiyat AS NUMERIC(10,2) PERMANENTLY;'], 'Sütun türü ALTER COLUMN ... TYPE ile değiştirilir; var olan değerler yeni türe dönüştürülür.'),
  ('PostgreSQL\'de ROUND(2.5) ve ROUND(3.5) ifadeleri NUMERIC değerler için sırasıyla ne verir?', '3 ve 4', ['2 ve 4', '2 ve 3', '3 ve 3'], 'PostgreSQL NUMERIC değerlerde yarımları sıfırdan uzağa yuvarlar.'),
  ('PostgreSQL\'de LENGTH(\'\') ve LENGTH(NULL) sırasıyla ne döndürür?', '0 ve NULL', ['NULL ve NULL', '0 ve 0', 'NULL ve 0'], 'Boş metin uzunluğu sıfır olan gerçek bir değerdir; NULL\'un uzunluğu ise bilinmez.'),
  ('PostgreSQL\'de eposta sütununda üç satır \'\', NULL ve \'a@b.com\' değerlerini tutuyorsa COUNT(eposta) kaç verir?', '2', ['1', '3', '0'], 'COUNT yalnız NULL\'u atlar; boş metin bir değer sayıldığı için sayılır.'),
  ('Formdan gelen boş metinleri NULL\'a çevirerek kaydetmek için hangi ifade kullanılabilir?', 'NULLIF(TRIM(girdi), \'\')', ['COALESCE(girdi, \'\')', 'LENGTH(girdi) = 0', 'COALESCE(NULLIF(girdi, NULL), \'\')'], 'TRIM boşlukları atar; sonuç boş metinse NULLIF onu NULL\'a çevirir.'),
  ('COUNT, MIN ve MAX fonksiyonlarının kullanılabildiği sütun türleri için hangisi doğrudur?', 'Üçü de metin ve tarihlerle çalışır', ['Yalnız COUNT sayısal olmayan sütunlarda çalışır', 'Üçü de yalnız sayısal sütunlarla çalışır', 'MIN ve MAX metinde çalışır, COUNT çalışmaz'], 'COUNT her türü sayar; MIN ve MAX sıralanabilen her türde en küçük ve en büyük değeri bulur.'),
  ('UPDATE Musteri m SET toplam = (SELECT SUM(tutar) FROM Siparis s WHERE s.mno = m.no); komutu hiç siparişi olmayan müşterilerin toplam alanına ne yazar?', 'NULL', ['0', 'Önceki değeri korur', 'Komut bu müşterilerde hata verip durur'], 'Eşleşen sipariş yoksa SUM NULL döndürür ve bu değer atanır; 0 istenirse COALESCE kullanılmalıdır.'),
  ('Maaşlar 9000, 9000, 7000 ve 5000 iken DENSE_RANK() OVER (ORDER BY maas DESC) = 2 koşulunu sağlayan satırlar hangi maaşa sahiptir?', '7000', ['9000', '5000', 'Koşulu sağlayan satır yoktur, sıra 3\'ten başlar'], 'DENSE_RANK iki 9000\'e 1, 7000\'e 2, 5000\'e 3 verir; boşluk bırakmadığı için n\'inci en yüksek farklı değeri bulmaya uygundur.'),
  ('Arsiv tablosu tamamen boşken, Urun sorgusundaki WHERE fiyat > (SELECT MAX(fiyat) FROM Arsiv) koşulu kaç satır seçer?', 'Hiç satır seçmez', ['Bütün satırları seçer', 'Yalnız fiyatı NULL olanları seçer', 'Hata verir, çünkü alt sorgu boştur'], 'Boş Arsiv için MAX NULL\'dur; fiyat > NULL karşılaştırması UNKNOWN olduğundan hiçbir satır koşulu sağlamaz.'),
  ('En çok satılan ürünün adını bulmak için hangi sorgu doğrudur?', 'SELECT u.ad FROM Kalem k JOIN Urun u ON u.id = k.urun_id GROUP BY u.id, u.ad ORDER BY SUM(k.adet) DESC LIMIT 1;', ['SELECT ad FROM Urun ORDER BY adet DESC LIMIT 1;', 'SELECT u.ad, MAX(k.adet) FROM Kalem k JOIN Urun u ON u.id = k.urun_id;', 'SELECT u.ad FROM Urun u JOIN Kalem k ON u.id = k.urun_id WHERE k.adet = (SELECT MAX(adet) FROM Kalem) LIMIT 1;'], 'Satış adetleri ürün başına toplanır, çoktan aza sıralanır ve ilk satır alınır.'),
  ('E-posta adresinin \'@\' işaretinden önceki kullanıcı adı kısmını PostgreSQL\'de alan ifade hangisidir?', 'SUBSTRING(eposta, 1, POSITION(\'@\' IN eposta) - 1)', ['SUBSTRING(eposta, POSITION(\'@\' IN eposta))', 'LEFT(eposta, \'@\')', 'SUBSTRING(eposta FROM POSITION(\'@\' IN eposta) + 1)'], '@ işaretinin konumundan bir eksiği kadar karakter baştan alınınca kullanıcı adı elde edilir.'),
  ('PostgreSQL\'de \'Sınıf \' || 9 ifadesinin sonucu nedir?', '\'Sınıf 9\'', ['Hata verir', '9', '\'Sınıf\''], 'PostgreSQL || işlecinde bir taraf metinse diğer taraftaki sayıyı da metne çevirir.'),
  ('Her öğrencinin kendi sınıfındaki öğrenci sayısını satırın yanına yazan ifade hangisidir?', 'COUNT(*) OVER (PARTITION BY sinif)', ['COUNT(*) GROUP BY sinif', 'COUNT(sinif) OVER (ORDER BY sinif ROWS 1 PRECEDING)', 'ROW_NUMBER() OVER (PARTITION BY sinif)'], 'PARTITION BY ile sayım her sınıfın penceresinde yapılır ve her satırda tekrarlanır.'),
  ('Siparis tablosunda her müşterinin kaçıncı siparişini verdiğini (1., 2., 3. ...) gösteren ifade hangisidir?', 'ROW_NUMBER() OVER (PARTITION BY mno ORDER BY tarih)', ['ROW_NUMBER() OVER (ORDER BY tarih)', 'COUNT(*) OVER (PARTITION BY mno)', 'RANK() OVER (PARTITION BY tarih ORDER BY mno)'], 'Her müşteri için numaralandırma baştan başlar ve tarihe göre ilerler.'),
  ('Bir mağaza her ürün için fiyatı, kategorideki ortalama fiyatla karşılaştırmak istiyor. AVG(fiyat) OVER (PARTITION BY kategori) ile GROUP BY kategori arasındaki seçimde pencere fonksiyonunun avantajı nedir?', 'Ürün satırları kaybolmadan her satırın yanına ortalama gelir', ['Ortalama daha doğru hesaplanır', 'Kategori sayısı azaltılır', 'Sorgu her durumda daha az bellek kullanır ve indeks gerektirmez'], 'GROUP BY kategoriye bir satır bırakır; pencere fonksiyonu ise ayrıntıyı korur.'),
  ('Notlar tablosunda her ders için en yüksek ve en düşük not arasındaki farkı 40\'tan fazla olan dersleri bulan koşul hangisidir?', 'HAVING MAX(puan) - MIN(puan) > 40', ['WHERE MAX(puan) - MIN(puan) > 40', 'HAVING puan - puan > 40', 'GROUP BY MAX(puan) - MIN(puan) > 40'], 'Grup düzeyindeki hesaplar HAVING\'de yazılır; iki kümeleme fonksiyonu tek ifadede birleşebilir.'),
  ('Puanlar sırayla (Ali 70), (Ece 70), (Can 60) iken RANK() OVER (ORDER BY puan DESC) ve ROW_NUMBER() OVER (ORDER BY puan DESC) Can için sırasıyla ne verir?', '3 ve 3', ['2 ve 3', '3 ve 2', '2 ve 2'], 'RANK eşitliklerden sonra boşluk bırakır (1, 1, 3); ROW_NUMBER ardışık numara verir (1, 2, 3). Can ikisinde de 3\'tür.'),
  ('Ders tablosunda kredi sütunu 2, 3 ve 4 değerlerini tutuyor. SELECT kredi FROM Ders WHERE kredi <> ALL (SELECT 3); sorgusu hangi değerleri döndürür?', '2 ve 4', ['Yalnız 3', '2, 3 ve 4', 'Hiçbir değer döndürmez'], '<> ALL, listedeki bütün değerlerden farklı olmayı ister; liste yalnız 3\'ü içerir.'),
  ('Bir Kitap tablosunda sayfa sayısı NULL olan kitaplar varken ORDER BY COALESCE(sayfa, 0) DESC sıralamasında bu kitaplar nerede görünür?', 'Sonda', ['Başta', 'Sonuçtan çıkarılır', 'Sayfa sayısı en büyük olan kitapların hemen arkasında, ortada'], 'NULL\'lar 0 kabul edilir; azalan sıralamada en küçük değerler sona düşer.'),
  ('Musteri tablosundaki şehir adlarında bazen sonda fazladan boşluk bırakıldığı için GROUP BY sehir aynı şehri iki grupta gösteriyor. Hangi düzeltme gruplamayı birleştirir?', 'GROUP BY TRIM(sehir)', ['GROUP BY DISTINCT sehir', 'GROUP BY sehir HAVING COUNT(*) > 1', 'GROUP BY LENGTH(sehir), sehir'], 'Boşluklar atılınca \'Bursa\' ile \'Bursa \' aynı değere döner ve tek grupta toplanır.'),
];
